function initBackGuard(){if(backGuardReady)return;backGuardReady=true;try{history.replaceState({srRoot:true},'',location.href);armBackGuard();window.addEventListener('popstate',()=>{let sm=$('#sourceModal'),setm=$('#settingsModal');if(sm&&!sm.classList.contains('hidden')){closeSource();armBackGuard();return}if(setm&&!setm.classList.contains('hidden')){setm.classList.add('hidden');armBackGuard();return}if(session||view!=='home'){navHome();setTimeout(armBackGuard,0);return}if(!backExitArmed){backExitArmed=true;toast('再返回一次可退出题库');clearTimeout(backRearmTimer);backRearmTimer=setTimeout(()=>{backExitArmed=false;armBackGuard()},1800);return}clearTimeout(backRearmTimer);backExitArmed=false})}catch(e){}}
function protectUnload(e){if(window.PWA_INSTALL?.state.reloadRequested){saveStore();return}if(isTimedSession())flushExamTimer();saveStore();if(isActiveExam()){saveSession();e.preventDefault();e.returnValue='';return ''}}


const knowledge=[
 {keys:['扭力扳手','力矩'],title:'扭矩工具',text:'扭力扳手的核心是按规定力矩进行紧固或复检。使用时通常要求受力平稳、工具与紧固件正确对中，并按校验/检定要求管理；达到设定值后应停止继续加力，避免过紧。'},
 {keys:['风扳机'],title:'风动工具',text:'风扳机用于快速预紧或紧固，必须按工艺规定选型并配套正确套筒。它不能替代扭力扳手的定量复检功能，持续冲击时间也应受控制。'},
 {keys:['随车单'],title:'随车单',text:'随车单与具体订单/车辆随行，用于承载装配、异常或后续处理等关联信息。记忆时把它理解成“跟着这台车走的记录载体”。'},
 {keys:['不合格品','不合格'],title:'不合格品控制',text:'不合格品管理的关键不是“先想办法继续生产”，而是先防止误用和混用。题库中的典型流程为隔离、标识、记录、审理、处置。'},
 {keys:['首件'],title:'首件管理',text:'首件检验的价值在于尽早发现换人、换料、换工装、设备调整等变化带来的系统性偏差，避免缺陷批量扩散。'},
 {keys:['质量检查点'],title:'质量检查点',text:'质量检查点强调把检验要求放到现场并可视化。题库相关内容包括检查点标识、检验文件、量检具、检验记录以及留存样件等。'},
 {keys:['4M1E','4M','变化点'],title:'4M1E变化点',text:'4M1E通常对应人（Man）、机（Machine）、料（Material）、法（Method）、环（Environment）。人员、设备、材料、方法或环境发生变化时，都可能带来质量波动，因此要进行变化点管理。'},
 {keys:['5S','整理','整顿'],title:'5S',text:'“整理”解决要与不要，“整顿”解决需要的物品放哪里、怎么快速找到。整顿强调定置、标识、取用方便和减少寻找时间，不要把“整理”和“整顿”的目的混在一起。'},
 {keys:['PDCA'],title:'PDCA循环',text:'PDCA按计划（Plan）—执行（Do）—检查（Check）—处置/改进（Act）循环推进。它不是一次性流程，而是持续改善、循环上升。'},
 {keys:['QC活动','QC小组'],title:'QC活动',text:'QC活动围绕问题选题、现状把握、目标设定、原因分析、对策与效果确认等步骤展开。题库第70题特别考查前四步的先后顺序。'},
 {keys:['标准作业','生产节拍','循环时间','作业顺序','标准手持'],title:'标准作业',text:'标准作业以人的动作为中心，常把生产节拍、作业顺序、标准手持作为关键要素。生产节拍回答“目标多久产一件”，循环时间回答“操作者完成一轮实际需要多久”，标准手持是维持节拍所需的最少在制品。'},
 {keys:['少人化','省人化'],title:'少人化与省人化',text:'少人化强调随生产量变化灵活配置最少人员；省人化更偏向通过改善或自动化减少人工作业。两者名称相近，是题库里的高频易混点。'},
 {keys:['自働化','自动化','均衡化'],title:'精益三概念',text:'自动化是设备代替人工作业；自働化强调把人的判断能力赋予设备，异常时能报警或停止；均衡化（平准化）则是把产品数量和种类尽量平均化生产。'},
 {keys:['MES'],title:'MES',text:'MES即制造执行系统，处在计划层与现场执行之间，关注从订单下达到产品完成过程中的执行、跟踪和现场资源状态。'},
 {keys:['BOM'],title:'BOM',text:'BOM是物料清单，用来描述一个最终产品由哪些零部件和原材料构成，以及数量等结构关系。'},
 {keys:['ERP'],title:'ERP',text:'ERP即企业资源计划，强调把财务、采购、生产、销售、库存等业务资源整合到统一管理平台。'},
 {keys:['TPM'],title:'TPM',text:'TPM强调全员参与的生产维护，目标是提高设备综合效率、减少故障和损失。题库还把设备点检、自主保养等内容与TPM联系起来。'},
 {keys:['点检','五定'],title:'设备点检',text:'点检是按规定项目和标准确认设备状态，常见“五定”包括定点、定法、定标、定期、定人。发现异常后应先消除异常并按要求确认设备状态，而不是凭经验带病运行。'},
 {keys:['KYT','危险预知'],title:'KYT',text:'KYT是危险预知训练，核心是作业前识别潜在危险、预测可能事故并形成预防措施，强调员工共同参与和现场纠正。'},
 {keys:['安全色','蓝色','红色'],title:'安全色',text:'安全色用于快速传递安全信息。题库中明确考到蓝色表示指令、必须遵守的约定；红色常用于禁止、停止或危险性更强的警示场景。'},
 {keys:['劳保','耳塞','安全帽','口罩'],title:'劳动防护',text:'劳保用品应根据岗位风险和作业内容配置，而不是凭个人感觉。噪声、粉尘、吊装等不同风险对应不同防护用品，进入生产区域前应按规定穿戴。'},
 {keys:['行车','吊装','吊具'],title:'吊装安全',text:'吊装作业强调额定能力、吊具状态和人员安全。不得超负荷、不明物不吊、吊物不得越过人员头顶；吊具出现裂纹、变形、凹槽等异常应按要求处理。'},
 {keys:['线束','管路'],title:'线束/管路装配',text:'线束和管路要做到走向合理、固定可靠、无干涉、无磨碰，并避开热源和尖锐部位。插接件要到位、可靠，装配后还要检查是否存在亏折、悬垂或交叉等问题。'},
 {keys:['防错'],title:'防错',text:'防错的目标是从设计和过程上避免错误发生，或在异常出现时立即识别并阻止继续流出。防错装置本身也需要点检，因为装置也可能失效。'},
 {keys:['纠正措施','预防措施','纠正是'],title:'纠正相关概念',text:'“纠正”侧重消除已经发现的不合格本身；“纠正措施”侧重消除导致不合格的原因，避免再次发生；“预防措施”针对潜在不合格或潜在不期望情况的原因。'},
 {keys:['看板'],title:'看板/目视化',text:'看板和可视化的核心是让生产状态、问题和需求一目了然，使现场人员能快速判断并采取行动。看板的发行数量和规则应随实际生产条件按制度调整。'},
 {keys:['七大浪费','浪费'],title:'七大浪费',text:'精益生产把不产生顾客价值的活动视为浪费。常见浪费包括等待、搬运、库存、不良/返修、过量生产、过度加工和多余动作等。'},
 {keys:['多技能','多能工'],title:'多技能工',text:'多技能工通过有计划的多岗位训练，使人员能在班组或产线内承担多个岗位，增强人员配置弹性，也是少人化的重要基础。'},
 {keys:['层级会议','一层级会议'],title:'层级会议',text:'层级会议用于逐级暴露和解决现场问题。一层级会议更贴近班组现场，通常围绕安全、质量关注点、生产任务等当班重点展开。'},
 {keys:['工装'],title:'工装管理',text:'工装要经过验证、点检/周检和必要的易损件管理。未经验证或验证不合格的工装不应投入生产；定位销、导套、定位块等易损件需按要求维护或更换。'},
 {keys:['ABS'],title:'ABS',text:'ABS的中文名称是防抱死制动系统。它通过防止制动时车轮完全抱死，帮助车辆保持一定的转向和稳定能力。'},
 {keys:['五大工具','APQP','PPAP','FMEA','SPC','MSA'],title:'质量五大工具',text:'汽车行业常说的质量五大工具为APQP、PPAP、FMEA、SPC、MSA。题库第130题直接考查这组缩写。'}
];
function matchedKnowledge(q){if(BANK_RUNTIME&&!BANK_RUNTIME.isHOS(q))return [];let t=q.stem+' '+q.options.join(' '),out=[];for(const k of knowledge){if(k.keys.some(x=>t.toLowerCase().includes(x.toLowerCase())))out.push(k);if(out.length>=2)break}return out}
function topicName(q){return (q.tags||[]).slice(0,2).join('、')||'现场管理'}
function genericSelectionReason(q,answers,know){let stem=displayText(q.stem),joined=answers.join('、');if(SELECTION_REASONS[q.id])return SELECTION_REASONS[q.id];if(/(日期|频次|责任单位|负责|标识线|代号|范围|期限|mm|\dT)/i.test(stem))return `“${joined}”是本题所依据的现场制度、工艺或编码中的明确要求。此类题的关键是把对象与规定值准确对应，实际执行仍以现场最新版文件为准。`;if(/(是指|称为|简称|定义|全称|中文名称)/.test(stem))return `题干给出的特征与“${joined}”的定义相符；其他相近概念只覆盖其中一部分，或适用对象不同。`;if(/(首先|第一时间|步骤|顺序|作业|操作|处理|使用)/.test(stem))return `“${joined}”能够满足题干所要求的操作顺序或控制目的，可先控制风险、质量状态或过程异常，避免问题继续扩大。`;if(know.length)return `选择“${joined}”的依据是：${know[0].text}`;return `题干考查${topicName(q)}中的具体要求。“${joined}”同时满足题干给出的对象、条件和目的，其他选项至少有一项关键限定不符合。`}
function trueJudgeReason(q,know){let tags=q.tags||[];if(JUDGE_REASONS[q.id])return JUDGE_REASONS[q.id];if(know.length)return `本题判“对”。判断依据是：${know[0].text}`;if(tags.includes('安全与劳保'))return '本题判“对”。题干要求针对作业危险源采取控制措施，能够降低人员受伤、误操作或事故扩大的风险。';if(tags.includes('质量管理'))return '本题判“对”。题干做法能够明确产品状态、保留过程证据或阻止不合格品继续流转，符合现场质量控制逻辑。';if(tags.includes('设备管理'))return '本题判“对”。按规定点检、停机、保养或确认设备状态，可以预防故障扩大并保证设备处于可用状态。';if(tags.includes('工具与装配'))return '本题判“对”。题干做法能够保护工具精度、保证装配一致性，并减少误用、磕碰或失效风险。';if(tags.includes('精益生产'))return '本题判“对”。题干做法围绕稳定流程、暴露问题和减少浪费展开，符合精益现场管理的基本逻辑。';if(tags.includes('生产与物流'))return '本题判“对”。题干要求能够保持生产与物料流转受控，使数量、状态和流向可识别、可追溯。';return '本题判“对”。题干中的对象、条件和动作能够完整对应，没有把适用范围扩大、缩小或省略关键步骤。'}
function optionReason(q,o,isCorrect,summary){let manual=OPTION_NOTES[q.id]?.[o];if(manual)return manual;let text=displayText(o);if(isCorrect)return `符合题干的关键条件。${fillEntry(q)?.why||summary}`;if(/以上都对|以上都是|全部正确/.test(text))return '只有在其余列项全部成立时才能选择该项；本题并不满足“全部成立”的条件。';if(/以上都不|都不正确|全部错误/.test(text))return '题目中存在符合要求的具体选项，因此不能作出“全部不正确”的判断。';if(/不用管|无所谓|随意|直接装|继续作业|继续生产|无需|不需要|大声咒骂|弄丢/.test(text))return '该做法绕过了标准作业、异常反馈或风险控制，可能让安全、质量或设备问题继续扩大。';if(/主任|班组长|质量|技术|部门|车间|个人|小组/.test(text)&&/(负责|反馈|报告|单位|人员|由|向)/.test(q.stem))return '责任主体与题目所述管理层级不匹配，不能替代规定的报告或处置责任人。';if(/[0-9]|每周|每天|每月|半年|黄色|红色|蓝色|白色/.test(text)&&/(日期|频次|间隔|代号|颜色|期限|mm|T)/i.test(q.stem))return '该数值、频次或标识与本题采用的工艺和管理标准不符。';if(/不属于|不包括|不正确|错误|不合适|不宜/.test(q.stem))return '该项正是题干要求识别的例外或错误做法，不能把它与其余合规项目混为一类。';return `该项与题干所限定的对象、条件或目的不完全一致，不能替代正确项“${questionAnswers(q).join('、')}”。`}
function objectiveAnalysis(q){return q.analysis||((!q.bankId||q.bankId==='hos_2026')?window.HOS_ANALYSIS?.[q.sourceQuestionId||q.id]:null)||null}
function objectiveReady(q){let a=objectiveAnalysis(q);return a?a.status==='ready':!window.EXPLANATION_CORE}
function structuredExplanation(q,renderType){let a=objectiveAnalysis(q);return {analysis:a||{topic:'解析尚未完成',why:'该旧题库未提供逐题核准的解释。请补充原始依据后再学习，系统不会以套话补造错因。',status:'missing'},summary:a?.why||'',correction:a?.correction||'',answers:[...q.answers],opts:q.type==='judge'?[]:q.options.map(o=>({text:o,ok:q.answers.includes(o),reason:a?.optionReasons?.[o]||'该选项的具体理由尚未提供。'})),know:[],memory:'',renderType}}
function explain(q,renderType=q.type,fillLevel='standard',fillVariantKey=''){if(renderType!=='fill'&&(window.EXPLANATION_CORE||BANK_RUNTIME))return structuredExplanation(q,renderType);if(BANK_RUNTIME&&!BANK_RUNTIME.isHOS(q)){let answers=questionAnswers(q,renderType,fillLevel,fillVariantKey),entry=renderType==='fill'?resolveFillEntry(q,fillLevel,fillVariantKey):null;let insight=q.bankId==='sinotruk_culture_2026'?window.CULTURE_INSIGHTS?.[q.sourceQuestionId]:null;return {summary:insight?insight[0]+'：'+insight[1]:entry?.why||q.explanation||SELECTION_REASONS[q.id]||'本题尚未提供核验解析，请以题库标准答案及原始资料为准。',correction:JUDGE_CORRECTIONS[q.id]||'',opts:renderType==='fill'||q.type==='judge'?[]:q.options.map(o=>({ok:q.answers.includes(o),text:o,reason:OPTION_NOTES[q.id]?.[o]||''})),know:[],memory:'先独立作答，再核对题库标准答案。',answers,renderType}};let know=matchedKnowledge(q),answers=questionAnswers(q,renderType,fillLevel,fillVariantKey),entry=renderType==='fill'?resolveFillEntry(q,fillLevel,fillVariantKey):null,summary='',correction='';if(q.type==='judge'&&renderType!=='fill'){if(q.answers[0]==='错'){correction=JUDGE_CORRECTIONS[q.id]||'题干存在不符合规定的表述，应去掉绝对化或省略关键条件的部分，并按现场标准改写。';summary=JUDGE_REASONS[q.id]||'本题判“错”。题干至少有一处做法、定义或适用条件与正确要求不一致；具体错误点和改正方法见下方。'}else summary=trueJudgeReason(q,know)}else summary=entry?.why||genericSelectionReason(q,answers,know);let opts=q.type==='judge'||renderType==='fill'?[]:q.options.map(o=>{let ok=q.answers.some(a=>cleanAns(a)===cleanAns(o));return {ok,text:displayText(o),reason:optionReason(q,o,ok,summary)}});let memory=renderType==='fill'?'遮住答案，按空格顺序完整写出关键词，再回看原题确认语境。':q.type==='multiple'?'把正确项按作业先后或检查对象整理成关键词组，复习时脱离选项完整说出。':q.type==='judge'?(q.answers[0]==='错'?'记住改正后的完整说法和错误原因，不要只背一个“错”字。':'把题干中的对象、条件和动作作为一条完整规则记忆。'):'把题干和答案连成一条完整规则，再到填空模式中主动回忆。';return {summary,correction,opts,know,memory,answers,renderType}}

function updateWatermark(){let e=$('#watermark');if(!e)return;let m=S.settings.watermark;e.textContent=m==='cn'?'神人刘':m==='en'?'SHENREN LIU':m==='off'?'':'神人刘 · SHENREN LIU';document.documentElement.dataset.theme=S.settings.theme||'light'}
function reviewQuestions(){let ids=new Set(Object.keys(S.reviewFlags||{}).filter(id=>S.reviewFlags[id]).map(Number));return Q.filter(q=>ids.has(q.id))}
function stats(){let seen=Q.filter(q=>S.seen[q.id]).length,fav=Q.filter(q=>S.favorites.includes(q.id)).length,wrong=Q.filter(q=>S.wrong[q.id]?.count>0).length,mastered=Q.filter(q=>S.mastery[q.id]==='mastered').length,review=reviewQuestions().length,due=Q.filter(q=>{let l=S.learning[q.id]||{};return l.due&&l.due<=Date.now()}).length;return {seen,fav,wrong,mastered,review,due}}
function backupMetrics(){let ag=S.aggregateStats||emptyAggregate();return {answers:num(ag.totalAnswers,0),exams:num(ag.totalExams,0),examsSchema:2,wrong:Object.values(S.wrong||{}).filter(x=>x&&((x.count||0)>0||(x.wrongTotal||0)>0)).length,favorites:(S.favorites||[]).length}}
function backupReminder(){if(window.QBANK_CLOUD_CONFIG?.enabled)return '';let now=Date.now(),m=backupMetrics(),last=S.settings.lastBackup||0,b=S.settings.lastBackupMetrics||{},active=m.answers>=20||m.exams>=2||m.wrong>=5||m.favorites>=5;if(!active||now<(S.settings.backupDismissedUntil||0))return '';let overdue=last&&now-last>7*86400000,changed=(m.exams-(b.exams||0)>=3)||(m.wrong-(b.wrong||0)>=5)||(m.favorites-(b.favorites||0)>=5);if(last&&!overdue&&!changed)return '';let message=last?'你的学习记录已有较多新增内容，建议导出一次，避免浏览器数据丢失。':'你已经产生了较多学习记录，但还没有备份，建议现在导出一次。';return `<div class="panel backup-reminder"><div><b>💾 数据备份提醒</b><span>${message}</span></div><div><button class="btn primary" onclick="${BANK_RUNTIME?'BANK_RUNTIME.openBackup()':'exportData()'}">立即备份</button><button class="btn" onclick="dismissBackupReminder()">稍后提醒</button></div></div>`}
function backupStatusText(){return S.settings.lastBackup?`上次备份：${new Date(S.settings.lastBackup).toLocaleDateString()}`:'从未备份：尚未备份'}
let renderScrollTicket=0;
// Answer-card position is owned by the current paper, independently of page scrolling.
function rememberSheetPosition(element){if(!element?.isConnected||!session||element?.closest?.('#answerPanel')?.dataset.paper!==session.paperId)return;session.sheetScrollTop=element.scrollTop;session.sheetPositionSaved=true;}
function captureSheetPosition(){const panel=$('#answerPanel'),sheet=panel?.querySelector?.('.answer-sheet');if(panel?.dataset.paper===session?.paperId&&sheet){rememberSheetPosition(sheet);return panel.classList.contains('open');}return false;}
function restoreSheetPosition(open=false){const owner=session,ticket=renderScrollTicket;requestAnimationFrame(()=>{if(owner!==session||ticket!==renderScrollTicket||view!=='question')return;const panel=$('#answerPanel'),sheet=panel?.querySelector?.('.answer-sheet');if(!sheet)return;if(owner.sheetPositionSaved)sheet.scrollTop=owner.sheetScrollTop||0;if(open&&window.matchMedia('(max-width:900px)').matches){panel.classList.add('open');$('.sheet-backdrop')?.classList.add('open');document.body.classList.add('sheet-open');}});}
function locateCurrentSheetQuestion(){const sheet=$('#answerPanel .answer-sheet'),item=sheet?.querySelector?.('.sheet-item.current');if(!sheet||!item)return;const a=sheet.getBoundingClientRect(),b=item.getBoundingClientRect();sheet.scrollTop=Math.max(0,sheet.scrollTop+b.top-a.top-(sheet.clientHeight-b.height)/2);rememberSheetPosition(sheet);}
function sheetItemMarkup(item,index,isFillStudy){const m=S.mastery[item.q.id],mastered=m==='mastered',completed=isFillStudy?!!item.viewed:isQuestionComplete(item),graded=item.checked&&typeof item.correct==='boolean',state=graded?(item.correct?'correct':'wrong'):completed?'answered':'unanswered',labels={correct:'答对',wrong:'答错',answered:isFillStudy?'已看':'已答待判',unanswered:isFillStudy?'未看':'未答'},mastery=mastered?'已掌握':m==='fuzzy'?'不熟，仍属未掌握':m==='new'?'未掌握':'未标记，仍属未掌握';return `<button class="sheet-item ${index===current?'current':''} ${completed?'done':'unanswered'} ${graded?state:''}" data-answer-state="${state}" data-mastery="${mastered?'mastered':'unmastered'}" aria-label="第${index+1}题，${labels[state]}，${mastery}${index===current?'，当前题':''}" ${index===current?'aria-current="step"':''} onclick="jumpQ(${index})"><span>${index+1}</span>${state==='answered'?'<i class="sheet-answer-mark" aria-hidden="true">•</i>':''}</button>`;}
function sheetLegend(){return '<div class="sheet-legend"><span><i class="legend-mastered" aria-hidden="true"></i> 浅绿底：已掌握</span><span><i class="legend-unmastered"></i> 白底：未掌握</span><span class="legend-correct">绿边：答对</span><span class="legend-wrong">红边：答错</span><span>• 已答／已看，未判对错</span><span>蓝色外框：当前题</span></div><details class="sheet-help"><summary>掌握状态说明</summary><p>掌握由你手动标记；未标记、不熟、未掌握都算未掌握。答对不自动等于已掌握。底色只表示掌握，边框只表示本轮判分。</p></details>';}
function masteryControl(q){const value=S.mastery[q.id]||'';return `<label class="mastery-control"><span>掌握状态</span><select class="btn" aria-label="本题掌握状态" onchange="setMastery(${q.id},this.value)"><option value="" ${!value?'selected':''}>未标记</option><option value="mastered" ${value==='mastered'?'selected':''}>已掌握</option><option value="fuzzy" ${value==='fuzzy'?'selected':''}>不熟</option><option value="new" ${value==='new'?'selected':''}>未掌握</option></select></label>`;}
let pendingPracticeScope=null;
function offerPracticeScope(pool,title,start){if(isActiveExam())return toast('请先保存退出或结束当前考试');if(!pool.length)return toast('当前范围没有可练习题目');pendingPracticeScope=start;let dialog=$('#practiceScopeDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='practiceScopeDialog';dialog.className='feedback-dialog practice-scope-dialog';document.body.append(dialog);}const remaining=filterMastery(pool,'unmastered').length;dialog.innerHTML=`<h2>开始前，选一下本轮范围</h2><p>${esc(title)}</p><div class="practice-scope-options"><button class="btn primary" onclick="confirmPracticeScope('all')"><b>全部题目</b><span>${pool.length}题 · 包含已掌握题目</span></button><button class="btn" ${remaining?'':'disabled'} onclick="confirmPracticeScope('unmastered')"><b>未掌握题目</b><span>${remaining}题 · 仅跳过已掌握</span></button></div><p class="muted">未标记和不熟也算未掌握。开始后仍可在“本轮设置”中切换。</p><button class="btn" onclick="cancelPracticeScope()">取消</button>`;dialog.showModal();}
function confirmPracticeScope(scope){if(!['all','unmastered'].includes(scope)||!pendingPracticeScope)return;const start=pendingPracticeScope;pendingPracticeScope=null;$('#practiceScopeDialog')?.close();start(scope);}
function cancelPracticeScope(){pendingPracticeScope=null;$('#practiceScopeDialog')?.close();}
function requestStudyStart(order='sequence'){offerPracticeScope(Q,order==='random'?'随机刷题':'顺序背题',scope=>startStudy(order,null,scope));}
function requestPracticeBatch(n){offerPracticeScope(Q,`随机刷题 · 最多${n}题`,scope=>startPracticeBatch(n,scope));}
function requestTodayReview(n){const count=Math.max(1,Math.min(Q.length,Number(n)||50));offerPracticeScope(Q,'今日复习 · 最多'+count+'题',scope=>startStudySession(filterMastery(todayReviewQuestions(Q.length),scope).slice(0,count),'今日复习',scope));}
function requestSpecialRecite(){const type=$('#specialType')?.value,level=$('#fillLevel')?.value||'enhanced';if(!SPECIAL_TYPES.includes(type))return toast('请先选择一种题型');offerPracticeScope(specialPool(type,level),typeName(type)+'专项背诵',scope=>startSpecialRecite(scope));}
function requestFillStart(order='sequence',level='enhanced',scope='all',batch=0){offerPracticeScope(trainingFillPool(level),'填空专项背诵',selected=>startFillStudy(order,level,selected,batch));}
function requestFavoriteStart(){offerPracticeScope(collectionPool('fav').filter(q=>S.favorites.includes(q.id)),'收藏夹练习',scope=>startFavoriteStudy(scope));}
function requestWrongStart(category='all'){const ids=new Set(wrongIds(category));offerPracticeScope(collectionPool('wrong').filter(q=>ids.has(q.id)),`错题练习 · ${wrongCategoryName(category)}`,scope=>startWrongCategory(category,scope));}

function collectionBankIds(kind){const available=BANK_RUNTIME?[...BANK_RUNTIME.ctx.metas.keys()]:[];const saved=S.settings.collectionBanks?.[kind];return Array.isArray(saved)?saved.filter(id=>available.includes(id)):available;}
function collectionPool(kind){if(!BANK_RUNTIME)return ALL_Q;const banks=new Set(collectionBankIds(kind));return ALL_Q.filter(q=>banks.has(q.bankId));}
function sanitizeCollectionBanks(value){const out={};for(const kind of ['fav','wrong'])if(Array.isArray(value?.[kind]))out[kind]=[...new Set(value[kind].filter(id=>typeof id==='string'&&BANK_RUNTIME?.ctx.metas.has(id)))];return out;}
function collectionBankPicker(kind){if(!BANK_RUNTIME)return '';const chosen=collectionBankIds(kind),has=q=>kind==='fav'?S.favorites.includes(q.id):(S.wrong[q.id]?.count>0||S.wrong[q.id]?.corrected);return `<fieldset class="panel collection-bank-picker"><legend>按题库整理 · 可多选</legend><div class="collection-bank-options">${[...BANK_RUNTIME.ctx.metas].map(([id,meta])=>{const count=ALL_Q.filter(q=>q.bankId===id&&has(q)).length;return `<label><input type="checkbox" data-collection-bank="${kind}" value="${id}" ${chosen.includes(id)?'checked':''} onchange="setCollectionBank('${kind}','${id}',this.checked)"><span>${esc(meta.name)}<small>${count}题</small></span></label>`}).join('')}</div><div class="q-actions"><button class="btn small" onclick="setAllCollectionBanks('${kind}',true)">全部题库</button><button class="btn small" onclick="setAllCollectionBanks('${kind}',false)">取消全选</button></div><p class="muted">这里单独选择错题／收藏的题库，可同时练多个库；学习记录始终保留。</p></fieldset>`;}
function setCollectionBank(kind,id,checked){if(!['fav','wrong'].includes(kind)||!BANK_RUNTIME?.ctx.metas.has(id))return;const ids=new Set(collectionBankIds(kind));checked?ids.add(id):ids.delete(id);const previous=S.settings.collectionBanks;S.settings.collectionBanks={...previous,[kind]:[...ids]};if(!saveStore()){S.settings.collectionBanks=previous;return;}kind==='fav'?renderFavoriteBook('preserve'):renderWrongBook('preserve');}
function setAllCollectionBanks(kind,checked){if(!['fav','wrong'].includes(kind))return;const previous=S.settings.collectionBanks;S.settings.collectionBanks={...previous,[kind]:checked?[...BANK_RUNTIME.ctx.metas.keys()]:[]};if(!saveStore()){S.settings.collectionBanks=previous;return;}kind==='fav'?renderFavoriteBook('preserve'):renderWrongBook('preserve');}
function ensureCollectionScope(kind,action,extra={}){if(!BANK_RUNTIME)return false;const ids=collectionBankIds(kind);if(!ids.length)return false;if([...ids].sort().join('|')===BANK_RUNTIME.scopeBankIds().slice().sort().join('|'))return false;if(!prepareRequiredPwaUpdate())return true;BANK_RUNTIME.applySelection(ids,{collectionStart:kind,collectionAction:action,...extra});return true;}
function restoreCollectionRoute(){if(!BANK_RUNTIME||typeof URL!=='function')return;const url=new URL(location.href),kind=url.searchParams.get('collectionStart'),action=url.searchParams.get('collectionAction');if(!['fav','wrong'].includes(kind)||!['study','exam'].includes(action))return;const scope=url.searchParams.get('collectionScope')==='unmastered'?'unmastered':'all',category=['all','recent','repeated','assisted','slow','corrected'].includes(url.searchParams.get('collectionCategory'))?url.searchParams.get('collectionCategory'):'all',count=Number(url.searchParams.get('collectionCount')),all=url.searchParams.get('collectionAll')==='1',strict=url.searchParams.get('collectionStrict')==='1';for(const key of [...url.searchParams.keys()])if(key.startsWith('collection'))url.searchParams.delete(key);history.replaceState(history.state,'',url.href);if(action==='study'){kind==='fav'?startFavoriteStudy(scope):startWrongCategory(category,scope);}else{renderCollectionExamSetup(kind,category);if($('#collectionCount'))$('#collectionCount').value=String(count);if($('#collectionRule'))$('#collectionRule').value=strict?'strict':'normal';beginCollectionExam(kind,all);}}
function decoratePracticeEntries(html){const names={startStudy:'requestStudyStart',startPracticeBatch:'requestPracticeBatch',startTodayReview:'requestTodayReview',startSpecialRecite:'requestSpecialRecite',startFillStudy:'requestFillStart',startFavoriteStudy:'requestFavoriteStart',startWrongCategory:'requestWrongStart',startWeakFill:'requestWeakFill',startReviewStudy:'requestReviewStart',startPendingPractice:'requestPendingPractice',startTagStudy:'requestTagStudy'};return html.replace(/onclick="(startStudy|startPracticeBatch|startTodayReview|startSpecialRecite|startFillStudy|startFavoriteStudy|startWrongCategory|startWeakFill|startReviewStudy|startPendingPractice|startTagStudy)\(([^"\n]*)\)"/g,(_,name,args)=>`onclick="${names[name]}(${args})"`);}
function requestWeakFill(level='enhanced'){const pool=trainingFillPool(level).filter(q=>S.difficultyProgress?.[q.id]?.review||num(S.wrong[q.id]?.count,0)>0);offerPracticeScope(pool,'薄弱填空复习',scope=>startWeakFill(level,scope));}
function requestPendingPractice(fromPaper=false){const source=fromPaper&&session?.finished?session:null,pool=source?source.items.filter(i=>!hasAnsweredValue(i.answer)).map(i=>i.q):Q.filter(q=>S.pendingPractice[q.id]);offerPracticeScope(pool,'待练清单',scope=>startPendingPractice(fromPaper,scope));}
function requestTagStudy(tag,bankScope='current'){offerPracticeScope((bankScope==='all'?ALL_Q:Q).filter(q=>q.tags?.includes(tag)),`专项：${tag}`,scope=>startTagStudy(tag,bankScope,scope));}
function requestReviewStart(){offerPracticeScope(reviewQuestions(),'待复核题目',scope=>startStudySession(reviewQuestions(),'待复核题目',scope));}

function pageHeaderHeight(){const header=$('.topbar');return header?.hidden?0:(header?.getBoundingClientRect?.().height??64)}
function app(html,scrollMode='top'){html=decoratePracticeEntries(html);if(view!=='question')document.body.classList.remove('sheet-open');const header=$('.topbar');if(header)header.hidden=view!=='home';window.LULU?.stop();let y=window.scrollY,ticket=++renderScrollTicket;$('#main').innerHTML=html;window.LULU?.loadImages();window.BEIJING_CLOCK?.render();window.ROUTINE_EGGS?.onView({home:view==='home',muted:!!S.settings.eggMuted});window.CLOUD_SYNC?.onView(view==='home');updateWatermark();updatePwaNotice();requestAnimationFrame(()=>{if(ticket!==renderScrollTicket)return;if(scrollMode==='preserve')window.scrollTo({top:y,behavior:'instant'});else if(scrollMode==='question'){let q=$('.question-focus')||$('.q-stem')||$('.section-title')||$('.question-card');if(q){let height=pageHeaderHeight();if(q.style)q.style.scrollMarginTop=(height+10)+'px';q.scrollIntoView({block:'start',behavior:'instant'})}else window.scrollTo({top:0,behavior:'instant'})}else window.scrollTo({top:0,behavior:'instant'})})}
function navHome(force=false){if(session&&session.kind!=='exam')persistPractice();closeEasterEgg();if(!force&&isActiveExam()&&!confirm('确定放弃当前考试吗？本卷进度将被清除。'))return;if(isTimedSession())pauseExamTimer();if(isActiveExam()){forgetActivity(session.paperId);S.lastSession=null;saveStore()}stopTimerTicker();document.body.classList.remove('sheet-open');view='home';session=null;current=0;renderHome()}

function shortcutCards(){return normalizeShortcuts(S.settings.homeShortcuts).map(id=>{let x=SHORTCUT_MAP[id];return modeCard(x.icon,x.title,x.desc,x.action,'core')}).join('')}
function renderShortcutEditor(){let box=$('#shortcutSettings');if(!box)return;shortcutEditorChanged=false;shortcutEditorReset=false;let current=normalizeShortcuts(S.settings.homeShortcuts),options=SHORTCUTS.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('');box.innerHTML=`<div class="shortcut-editor-title"><div><b>首页快捷入口</b><span>自由选择 4 个，保存后立即生效</span></div><button class="btn small" type="button" onclick="restoreDefaultShortcuts()">恢复默认</button></div><div class="shortcut-editor-grid">${current.map((id,i)=>`<label><span>快捷入口 ${i+1}</span><select class="btn shortcutSetting" data-slot="${i}" onchange="markShortcutsCustomized()">${options}</select></label>`).join('')}</div>`;$$('.shortcutSetting',box).forEach((el,i)=>el.value=current[i])}
function markShortcutsCustomized(){shortcutEditorChanged=true;shortcutEditorReset=false}
function restoreDefaultShortcuts(){shortcutEditorChanged=false;shortcutEditorReset=true;$$('.shortcutSetting').forEach((el,i)=>el.value=DEFAULT_SHORTCUTS[i]);toast('已恢复默认选择，请点保存设置')}
function openShortcutSettings(){openSettings();requestAnimationFrame(()=>$('#shortcutSettings')?.scrollIntoView({block:'center',behavior:'smooth'}))}
function renderHome(){view='home';migrateRecentSessions();const st=stats();app(`
<section class="hero compact-hero"><div class="panel hero-main lulu-hero"><div class="hero-copy"><div class="hero-heading"><h1><span>神人刘题库</span><span>训练站</span></h1></div><div class="hero-caption"><button class="hero-bank-picker" type="button" onclick="window.BANK_RUNTIME?.openSelector()" aria-haspopup="dialog"><span class="hero-bank-label">选择题库<span class="hero-bank-arrow" aria-hidden="true">›</span></span><span class="hero-bank-current">${BANK_RUNTIME?esc(BANK_RUNTIME.exportBankSummary()):'HOS 应知应会'}</span>${BANK_RUNTIME?.errors.length?'<span class="hero-bank-error">部分题库未加载，点击查看</span>':''}</button></div></div><div class="lulu-mascot"><span id="luluSpeech" class="lulu-speech" aria-hidden="true">点击我试试吧～</span><button id="luluHomeButton" class="lulu-button" type="button" onclick="openLuluRoom()" aria-label="水豚噜噜：打开学习记录和掌握地图" title="水豚噜噜 · 点击探索学习小屋">${window.LULU?.imageMarkup(512,512)||'<img src="lulu-mascot.png" width="512" height="512" alt="" draggable="false">' }<span class="lulu-label">水豚噜噜 · 点击探索</span></button></div></div><div class="panel status-overview"><b>学习状态概览</b><div><span>题库<strong>${Q.length}</strong></span><span>已练习<strong>${st.seen}</strong></span><span>未覆盖<strong>${Q.length-st.seen}</strong></span><span>错题<strong>${st.wrong}</strong></span><span>收藏<strong>${st.fav}</strong></span><span>到期复习<strong>${st.due}</strong></span></div></div></section>
${window.STUDY_PLANS?.home?.()||''}
${recentSessionsMarkup()}
${contentTopicPicker()}${officialCultureNotice()}${DATA_WARNINGS.length?`<div class="notice danger-notice"><b>数据安全提示：</b>${esc([...new Set(DATA_WARNINGS)].join('；'))}</div>`:''}
${BANK_AUDIT_ERRORS.length?`<div class="notice danger-notice"><b>题库数据自检未通过：</b>${esc(BANK_AUDIT_ERRORS.slice(0,5).join('；'))}</div>`:`<details class="integrity-detail"><summary>题库完整性检查通过</summary><p>题库数据自检通过 · ${Q.length}道有效题，题库身份、原题编号及答案映射正常。</p></details>`}
${backupReminder()}<div class="home-text-links"><details><summary>统计说明</summary><p>概览仅统计当前所选题库。已练习为看过的题，不代表掌握；到期复习为已设置复习日期且到期的题。地图的待巩固还包括错题、不熟题。待练、到期复习与错题可能重叠，不能相加作为总题数。旧版累计记录保留原值，2026-10-21前为空白与答错混合口径。</p></details></div>
<div class="section-title shortcut-title"><div><h2>我的快捷入口</h2><p>这 4 个入口由你自己决定</p></div><button class="btn small" onclick="openShortcutSettings()">编辑快捷入口</button></div><section class="mode-grid core-mode-grid">
${shortcutCards()}
</section><div class="section-title"><div><h2>错题与收藏</h2><p>高频复习入口，集中巩固个人薄弱点</p></div></div><section class="mode-grid personal-entry">${['wrong','favorites'].map(id=>{let x=SHORTCUT_MAP[id];return modeCard(x.icon,x.title,x.desc,x.action)}).join('')}</section>
<details class="more-modes panel" ${S.settings.allModesOpen?'open':''} ontoggle="rememberModesOpen(this.open)"><summary>所有训练模式</summary><p class="muted">常用入口已列在上方，这里补充其余模式；全部功能仍可使用</p><section class="mode-grid">
${MODE_REGISTRY.filter(x=>x.showInAllModes!==false&&(!isOfficialCultureScope()||x.id!=='openConcept')&&!normalizeShortcuts(S.settings.homeShortcuts).includes(x.id)).map(x=>modeCard(x.icon,x.title,x.desc,x.action)).join('')}
</section></details>
<div class="section-title"><div><h2>学习进度</h2><p id="studyStorageHint">${window.CLOUD_SYNC?.connected?.()?'学习记录已关联账号，换设备登录即可继续':'当前使用本机记录，登录账号后可跨设备同步'}</p></div></div><section class="dashboard-grid"><div class="panel pad"><b>总体覆盖</b><div class="progressbar" style="margin:12px 0 7px"><i style="width:${Math.round(st.seen/Q.length*100)}%"></i></div><span class="muted">已练 ${st.seen}/${Q.length} 题 · ${Math.round(st.seen/Q.length*100)}%</span></div>${window.QBANK_CLOUD_CONFIG?.enabled?`<div class="panel pad"><b>账号与同步</b><p class="muted">${window.CLOUD_SYNC?.connected?.()?'学习记录自动同步到同一账号，换设备直接登录即可。':'登录账号后，收藏、错题和练习进度可以跨设备继续。'}备份与恢复已收进设置。</p><button class="btn primary" onclick="CLOUD_SYNC.open()">${window.CLOUD_SYNC?.connected?.()?'查看账号与同步':'登录，跨设备同步'}</button></div>`:`<div class="panel pad"><b>备份学习数据</b><p class="muted backup-status">${backupStatusText()} · 换手机或清浏览器前请先导出。</p><div class="backup-actions">${BANK_RUNTIME?'<button class="btn primary" onclick="BANK_RUNTIME.openBackup()">备份与换设备</button>':`<button class="btn small primary" onclick="openTransfer()">复制码迁移</button><button class="btn small" onclick="exportData()">完整文件备份</button><button class="btn small" onclick="$('#importFile').click()">导入文件</button>`}<input id="importFile" type="file" accept="application/json" hidden onchange="importData(this.files[0])"></div></div>`}</section>`);window.LULU?.mount()}
let lastLuluOrange=-1;
function luluOrangeLine(){return window.LULU_FORTUNES?.draw?.()||'慢慢学，噜噜陪你。'}
function drawLuluOrangeNote(){const note=$('#luluOrangeNote');if(note)note.textContent=luluOrangeLine()}
function openLuluRoom(){if(isActiveExam())return toast('请先结束当前考试，再找噜噜玩');if(isTimedSession())pauseExamTimer();stopTimerTicker();view='luluRoom';session=null;document.body.classList.remove('sheet-open');app(`<div class="section-title"><div><h2>噜噜的学习小屋</h2><p>水豚噜噜：随便坐，进步都帮你记着呢。</p></div><button class="btn" onclick="navHome()">返回题库</button></div><div class="panel lulu-room-welcome">${window.LULU?.imageMarkup(112,112,'戴橘子帽的水豚噜噜')||'<img src="lulu-mascot.png" width="112" height="112" alt="戴橘子帽的水豚噜噜">' }<div><b>被你发现啦！</b><p>想回看考试，还是看看哪些题已经拿下？</p><small class="muted">这里只打开已有学习记录，不会改动你的数据。</small></div></div><section class="mode-grid lulu-room-entries">${modeCard('📊','学习记录','查看考试记录、累计成绩与薄弱知识点',"openLuluPage('history')")}${modeCard('🗺️','当前范围掌握地图','查看全库掌握状态和待复习题',"openLuluPage('mastery')")}${modeCard('📝','待练清单',`当前范围 ${Q.filter(q=>S.pendingPractice[q.id]).length} 道考试留白题，找个时间慢慢补`,"startPendingPractice()")}</section><section class="panel lulu-orange-note"><div><b>🍊 噜噜橘子签</b><p id="luluOrangeNote" role="status" aria-live="polite">${esc(luluOrangeLine())}</p></div><button class="btn small" onclick="drawLuluOrangeNote()">再抽一句</button></section>`)}
function openLuluPage(page){if(isActiveExam())return toast('请先结束当前考试');if(page==='history')renderHistory();else if(page==='mastery')renderMasteryMap();else return;let header=$('.section-title');if(header){let back=header.querySelector('button');if(back){back.textContent='返回噜噜小屋';back.setAttribute('onclick','openLuluRoom()')}}}

function modeCard(icon,title,desc,onclick,level=''){if(contentTopicId()!=='all'&&onclick.includes('renderRealExamSetup')){title='分类专项模拟';desc='只从当前内容分类选题，按题型和题量集中测试'}if(Q.length&&Q.every(q=>q.type==='fill')&&onclick.includes('renderRealExamSetup')){title='填空模拟';desc='当前为纯填空题库，最多 '+Q.length+'题，逐空核对答案'}if(onclick==="startStudy('random')")onclick="renderPracticeSetup()";return `<div class="panel mode-card ${level?'mode-'+level:''}"><div class="mode-icon">${icon}</div><h3>${title}</h3><p>${desc}</p><button class="btn primary small" onclick="${onclick}">进入</button></div>`}

function todayReviewQuestions(limit=50){let now=Date.now();return Q.map(q=>{let l=S.learning[q.id]||{},wrong=S.wrong[q.id]?.count||0,mastery=S.mastery[q.id]||'',seen=S.seen[q.id]||0,avg=l.attempts?l.totalMs/l.attempts:0,score=wrong*100+(mastery==='fuzzy'?70:mastery==='new'?40:0)+(l.due&&l.due<=now?35:0)+(avg>=30000?25:0)+(seen?Math.min(20,(now-seen)/86400000):30);return {q,score}}).sort((a,b)=>b.score-a.score||a.q.id-b.q.id).slice(0,limit).map(x=>x.q)}
function startTodayReview(limit=50){startStudySession(todayReviewQuestions(Math.max(1,Math.min(Q.length,Number(limit)||50))),'今日复习')}

function buildItems(list,mode='study',fillRatio=0,fillLevel='standard'){let arr=list.map(q=>({q,renderType:q.type,fillLevel:'standard',answer:null,checked:false,correct:null,showExplanation:false,assisted:false,revealed:false,attemptRecorded:false,confidence:'',timeMs:0,optionOrder:[...q.options],fillVariantKey:''}));if(mode==='fill'){arr=arr.filter(x=>isFillEligible(x.q,fillLevel)).map(x=>({...x,renderType:'fill',fillLevel}))}else if(mode==='mixed'&&fillRatio>0){let eligible=shuffle(arr.filter(x=>isFillEligible(x.q)));let n=Math.min(eligible.length,Math.round(arr.length*fillRatio/100));let ids=new Set(eligible.slice(0,n).map(x=>x.q.id));arr=arr.map(x=>ids.has(x.q.id)?{...x,renderType:'fill'}:x)}return arr}
function filterMastery(list,scope='all'){return scope==='unmastered'?list.filter(q=>S.mastery[q.id]!=='mastered'):list}
function enableStudyScope(scope='all'){session.masteryPool=[...session.items];session.masteryScope=scope==='unmastered'?'unmastered':'all';session.items=session.masteryScope==='unmastered'?session.masteryPool.filter(i=>S.mastery[i.q.id]!=='mastered'):[...session.masteryPool]}
function thinkBeforeSelectActive(item){return !!(S.settings.thinkBeforeSelect&&session?.masteryPool&&session.kind!=='exam'&&!session.reviewMode&&['single','multiple'].includes(item?.renderType))}
function hideStudyOptions(item){return thinkBeforeSelectActive(item)&&!item.optionsRevealed&&!item.checked&&!item.revealed&&!item.showExplanation&&!hasAnsweredValue(item.answer)}
function thinkBeforeSelectControl(){return `<label class="think-select-toggle"><input type="checkbox" ${S.settings.thinkBeforeSelect?'checked':''} onchange="setThinkBeforeSelect(this.checked)"><span>先想再选</span><small>单选、多选先隐藏选项，想好再展开</small></label>`}
function setThinkBeforeSelect(enabled){if(isActiveExam())return;S.settings.thinkBeforeSelect=enabled===true;saveStore();if(view==='question'&&session)renderQuestion('preserve')}
function revealStudyOptions(){let item=session?.items?.[current];if(!thinkBeforeSelectActive(item))return;item.optionsRevealed=true;renderQuestion('preserve')}
function studyScopeControls(){if(!session?.masteryPool||session.kind==='exam'||session.reviewMode)return '';let all=session.masteryPool.length,pending=session.masteryPool.filter(i=>S.mastery[i.q.id]!=='mastered').length;return `<div class="notice study-scope"><div class="q-actions" role="group" aria-label="学习范围"><button class="btn ${session.masteryScope==='all'?'primary':''}" aria-pressed="${session.masteryScope==='all'}" onclick="setStudyScope('all')">全部题目（${all}）</button><button class="btn ${session.masteryScope==='unmastered'?'primary':''}" aria-pressed="${session.masteryScope==='unmastered'}" onclick="setStudyScope('unmastered')">未掌握题目（${pending}）</button></div>${session.masteryPool.some(i=>['single','multiple'].includes(i.renderType))?thinkBeforeSelectControl():''}<p>未掌握包括未标记、不熟和未掌握；仅跳过你明确标为“已掌握”的题。${session.masteryScope==='unmastered'?'标为已掌握后自动移出本轮。':''}</p></div>`}
function setStudyScope(scope){if(!session?.masteryPool||session.kind==='exam'||session.reviewMode||!['all','unmastered'].includes(scope))return;let active=session.items[current];if(isTimedSession())flushExamTimer();session.masteryScope=scope;session.items=scope==='unmastered'?session.masteryPool.filter(i=>S.mastery[i.q.id]!=='mastered'):[...session.masteryPool];let found=session.items.indexOf(active);current=found>=0?found:Math.max(0,Math.min(current,session.items.length-1));if(isTimedSession()){session._activeIndex=current;session._activeSince=session.items.length&&!document.hidden?performance.now():null}renderQuestion(active&&session.items[current]!==active?'question':'preserve')}
function startStudySession(list,title,scope=null){title=contentTopicTitle(title,list);let origin=['search','masteryMap','history','review','favorites','wrongBook'].includes(view)?capturePracticeFrame():null;view='question';let paperId=makePaperId(),items=applyOptionOrders(buildItems(list,'study'),paperId);session={kind:'study',items,started:Date.now(),title,paperId,finished:false,...(origin?{parentFrame:origin}:{})};if(scope!==null)enableStudyScope(scope);current=0;initExamTimer();renderQuestion()}
function startStudy(order='sequence',list=null,scope='all'){let qs=list||Q;if(order==='random')qs=shuffle(qs);startStudySession(qs,order==='random'?'随机刷题':'顺序背题',list===null?scope:null)}
function rememberModesOpen(open){if(S.settings.allModesOpen===!!open)return;S.settings.allModesOpen=!!open;saveStore()}
function rememberQuestionPreferences(open){if(session)session.questionPreferencesOpen=!!open}
function questionPreferences(recite){let scope=studyScopeControls();if(!scope&&!recite)return '';return `<details class="question-preferences" ${session.questionPreferencesOpen?'open':''} ontoggle="if(this.isConnected)rememberQuestionPreferences(this.open)"><summary>本轮设置<span>${session.masteryPool?(session.masteryScope==='unmastered'?'未掌握题目':'全部题目'):''}${recite?' · 背诵偏好':''}</span></summary><div class="question-preferences-body">${scope}${recite?reciteControls():''}</div></details>`}
function reciteControls(){if(thinkBeforeSelectActive(session?.items?.[current]))return '<p class="muted">先想再选已开启，提交后可核对答案；直接看答案仍记为辅助学习。</p>';return `<div class="notice recite-controls"><label>背诵答案 <select class="btn" onchange="setReciteAnswerMode(this.value)"><option value="manual" ${S.settings.reciteAnswers!=='always'?'selected':''}>逐题点击查看（默认）</option><option value="always" ${S.settings.reciteAnswers==='always'?'selected':''}>一直显示答案</option></select></label>${S.settings.reciteAnswers!=='always'&&session.kind!=='fillStudy'?'<button class="btn small" onclick="revealReciteAnswer()">查看／隐藏本题答案</button>':''}</div>`}
function setReciteAnswerMode(mode){if(isActiveExam())return;S.settings.reciteAnswers=mode==='always'?'always':'manual';if(session)for(const item of session.items){item.reciteRevealed=false;if(!item.checked){item.showExplanation=false;if(item.revealed){item.answer=null;item.revealed=false}}}saveStore();renderQuestion('preserve')}
function revealReciteAnswer(){if(!session||isActiveExam())return;let item=session.items[current];if(S.settings.reciteAnswers==='always'&&!thinkBeforeSelectActive(item)){S.settings.reciteAnswers='manual';item.reciteRevealed=false}else item.reciteRevealed=!item.reciteRevealed;if(item.reciteRevealed){item.assisted=true;item.revealed=true;}saveStore();renderQuestion('preserve');exposeSubmittedFeedback()}
function collectionIds(kind,category='all'){return kind==='fav'?collectionPool('fav').filter(q=>S.favorites.includes(q.id)).map(q=>q.id):wrongIds(category)}
function renderFavoriteBook(scrollMode='top'){view='favorites';let n=collectionIds('fav').length;app(`<div class="section-title"><div><h2>收藏夹</h2><p>所选题库共 ${n} 题 · 可背诵，也可从收藏题生成测试</p></div><button class="btn" onclick="navHome()">返回题库</button></div>${collectionBankPicker('fav')}<div class="panel pad backup-actions"><button class="btn primary" onclick="startFavoriteStudy()" ${n?'':'disabled'}>复习全部</button><button class="btn primary" onclick="renderCollectionExamSetup('fav')" ${n?'':'disabled'}>抽题测试</button><button class="btn" onclick="beginCollectionExam('fav',true)" ${n?'':'disabled'}>全部测试</button></div>`,scrollMode)}
function startFavoriteStudy(scope='all'){let list=collectionPool('fav').filter(q=>S.favorites.includes(q.id));if(!list.length)return toast('收藏夹还是空的');if(ensureCollectionScope('fav','study',{collectionScope:scope}))return;startStudySession(list,'收藏夹',scope)}
function renderCollectionExamSetup(kind,category='all'){if(isActiveExam())return toast('请先结束当前考试');kind=kind==='fav'?'fav':'wrong';let ids=collectionIds(kind,category),max=ids.length;view='examSetup';app(`<div class="panel exam-setup"><div class="section-title"><div><h2>${kind==='fav'?'收藏夹':'错题本'}测试</h2><p>从自己的题目中随机抽取；可选全部，考试中隐藏答案和解析</p></div><button class="btn" onclick="${kind==='fav'?'renderFavoriteBook()':'renderWrongBook()'}">返回</button></div>${kind==='wrong'?`<div class="field"><label>错题范围</label><select class="btn" id="collectionCategory" onchange="renderCollectionExamSetup('wrong',this.value)">${['all','recent','repeated','assisted','slow','corrected'].map(k=>`<option value="${k}" ${category===k?'selected':''}>${wrongCategoryName(k)}（${wrongIds(k).length}题）</option>`).join('')}</select></div>`:''}<div class="field"><label>题目数量（当前 ${max} 题）</label><input id="collectionCount" class="btn" type="number" min="1" max="${max}" step="1" value="${Math.min(20,max)}"></div><div class="field"><label>交卷规则</label><select id="collectionRule" class="btn"><option value="normal">普通模式（未答可交卷）</option><option value="strict">严格模式（必须全部作答）</option></select></div><p class="muted">收藏题使用原题型；错题优先保留上次出错时的题型和挖空位置，旧记录没有快照时使用原题。全部测试保留每个原题号。</p><div class="backup-actions"><button class="btn primary" onclick="beginCollectionExam('${kind}',false)" ${max?'':'disabled'}>开始抽题测试</button><button class="btn" onclick="beginCollectionExam('${kind}',true)" ${max?'':'disabled'}>全部测试 ${max} 题</button></div></div>`)}
function beginCollectionExam(kind,all=false){if(isActiveExam())return toast('请先结束当前考试');kind=kind==='fav'?'fav':'wrong';let category=kind==='wrong'&&view==='examSetup'?($('#collectionCategory')?.value||'all'):'all',ids=collectionIds(kind,category),n=all?ids.length:Number($('#collectionCount')?.value);if(!Number.isInteger(n)||n<1||n>ids.length)return toast(`题量须为1～${ids.length}之间的整数`);if(ensureCollectionScope(kind,'exam',{collectionCategory:category,collectionCount:String(n),collectionAll:all?'1':'0',collectionStrict:view==='examSetup'&&$('#collectionRule')?.value==='strict'?'1':'0'}))return;let chosen=shuffle(ids).slice(0,n),paperId=makePaperId(),items=kind==='wrong'?wrongReviewRecords(chosen).map(restoredReviewItem).filter(Boolean):applyOptionOrders(buildItems(chosen.map(id=>ALL_Q.find(q=>q.id===id)),'study'),paperId);for(const item of items){delete item.reviewSource;item.answer=null;item.checked=false;item.correct=null;item.showExplanation=false;item.assisted=false;item.revealed=false;item.attemptRecorded=false;item.timeMs=0;capturePresentation(item)}if(items.some(i=>i.renderType!=='fill'&&!objectiveReady(i.q)))return toast('所选记录含待核验原题，请查看解析；暂不创建这场测试');if(items.length!==n)return toast('题目记录异常，已阻止测试');session={kind:'exam',mode:'collection_exam',collectionKind:kind,items,started:Date.now(),title:kind==='fav'?'收藏夹测试':'错题本测试',strict:view==='examSetup'&&$('#collectionRule')?.value==='strict',finished:false,rotationRecorded:false,paperId};current=0;initExamTimer();saveSession();renderQuestion()}

function renderFillStudySetup(){renderSpecialSetup('recite','fill')}
function startFillStudy(order='sequence',level='enhanced',scope='all',batch=0){let choice=['multi','concept'].includes(level)?level:'enhanced';level=choice==='enhanced'?'enhanced':'ultra';view='question';let qs=trainingFillPool(choice);if(!qs.length)return toast('已审核候选不足，暂无可练习题');if(order==='random')qs=shuffle(qs);if(batch)qs=filterMastery(qs,scope).slice(0,batch);let items=assignFillVariantKeys(buildItems(qs,'fill',0,level));items.forEach(capturePresentation);session={kind:'fillStudy',mode:'special_recite',questionType:'fill',fillLevel:level,items,started:Date.now(),title:contentTopicTitle(`填空专项背诵 · ${choice==='concept'?'概念客观填空':choice==='multi'?'高难多空':'基础填空'}`,qs)};enableStudyScope(scope);current=0;renderQuestion()}
function startBalancedReview(){startTodayReview()}
function sprintPriority(q){let now=Date.now(),l=S.learning[q.id]||{},w=S.wrong[q.id]||{},attempts=l.attempts||0,accuracy=attempts?(l.correct||0)/attempts:0,avg=l.timedAttempts?l.totalMs/l.timedAttempts:0,last=l.last||S.seen[q.id]||0,days=last?Math.min(60,(now-last)/86400000):60,usage=num(S.examRotation?.usage?.[q.id],0),recent=(S.examRotation?.recent||[]).slice(-3).some(ids=>ids.includes(q.id));return (w.wrongTotal||w.count||0)*30+(w.wrongStreak||0)*45+(w.lastWrong&&now-w.lastWrong<7*86400000?35:0)+(l.lowConfidenceCorrect||0)*18+(l.assistedCorrect||0)*15+(avg>=30000?25:avg>=20000?12:0)+(l.due&&l.due<=now?30:0)+(1-accuracy)*20+days*.7-Math.min(30,usage*3)-(recent?28:0)}
function sprintQuestions(n=30){let usedGroups=new Set(),tagCounts={},ranked=Q.map(q=>({q,score:sprintPriority(q)+Math.random()*5})).sort((a,b)=>b.score-a.score),out=[];for(const x of ranked){let group=duplicateKey(x.q.id),tags=x.q.tags||[],crowded=tags.length&&tags.every(t=>(tagCounts[t]||0)>=Math.max(2,Math.ceil(n/8)));if(usedGroups.has(group)||crowded)continue;out.push(x.q);usedGroups.add(group);for(const tag of tags)tagCounts[tag]=(tagCounts[tag]||0)+1;if(out.length>=n)break}if(out.length<n)for(const x of ranked){if(out.includes(x.q)||usedGroups.has(duplicateKey(x.q.id)))continue;out.push(x.q);usedGroups.add(duplicateKey(x.q.id));if(out.length>=n)break}return out}
function renderSprintSetup(){view='examSetup';app(`<div class="panel exam-setup"><div class="section-title" style="margin-top:0"><div><h2>🚀 考前冲刺</h2><p>优先安排反复错、最近错、低信心、高耗时、到期和覆盖不足题</p></div><button class="btn" onclick="navHome()">返回</button></div><div class="field"><label>本轮题量</label><div class="count-buttons" id="sprintCountBtns">${[20,30,50].map(n=>`<button class="btn ${n===30?'active':''}" data-n="${n}">${n}题</button>`).join('')}</div></div><div class="notice" style="margin-top:16px">会兼顾知识点和历史曝光，避免少数错题无限重复；交卷后给出高风险、高耗时与改善情况。</div><div style="margin-top:18px"><button class="btn primary" onclick="startSprint()">开始冲刺</button></div></div>`);$$('#sprintCountBtns button').forEach(b=>b.onclick=()=>{$$('#sprintCountBtns button').forEach(x=>x.classList.remove('active'));b.classList.add('active')})}
function startSprint(){let n=Number($('#sprintCountBtns .active')?.dataset.n||30),picked=sprintQuestions(n);if(picked.length!==n)return toast('冲刺题量生成异常，请重试');let paperId=makePaperId(),items=applyOptionOrders(buildItems(picked,'study'),paperId);if(items.some(i=>i.renderType!=='fill'&&!objectiveReady(i.q)))return toast('题目含待核验项，请使用已核验的真实模拟');session={kind:'exam',mode:'sprint',fillLevel:'standard',strict:false,items,started:Date.now(),title:'考前冲刺',finished:false,rotationRecorded:false,paperId};current=0;initExamTimer();saveSession();renderQuestion()}
function openCollection(kind){return kind==='fav'?renderFavoriteBook():renderWrongBook()}
function wrongCategory(id){let w=S.wrong[id]||{},l=S.learning[id]||{},avg=l.timedAttempts?l.totalMs/l.timedAttempts:0;if(w.corrected)return 'corrected';if((w.wrongStreak||0)>=2||(w.wrongTotal||0)>=3)return 'repeated';if(w.recentResult==='assistedCorrect')return 'assisted';if(avg>=30000)return 'slow';return 'recent'}
function wrongCategoryName(k){return {recent:'刚做错',repeated:'反复错',assisted:'辅助后会做',slow:'高耗时',corrected:'已纠正待巩固'}[k]||'全部'}
function wrongIds(category='all'){return Object.keys(S.wrong).map(Number).filter(id=>collectionPool('wrong').some(q=>q.id===id)).filter(id=>{let w=S.wrong[id];return w&&(w.count>0||w.corrected)&&(category==='all'||wrongCategory(id)===category)})}
function renderWrongBook(scrollMode='top'){view='wrongBook';let cats=['recent','repeated','assisted','slow','corrected'],all=wrongIds();app(`<div class="section-title"><div><h2>错题本</h2><p>连续2次独立答对后转为已纠正待巩固</p></div><button class="btn" onclick="navHome()">返回</button></div>${collectionBankPicker('wrong')}<div class="setup-grid">${cats.map(k=>`<button class="panel mode-card" onclick="startWrongCategory('${k}')"><h3>${wrongCategoryName(k)}</h3><p>${wrongIds(k).length}题</p></button>`).join('')}</div><div style="margin-top:16px"><button class="btn primary" onclick="startWrongCategory('all')" ${all.length?'':'disabled'}>练全部 ${all.length} 题</button> <button class="btn primary" onclick="renderCollectionExamSetup('wrong')" ${all.length?'':'disabled'}>抽题测试</button> <button class="btn" onclick="beginCollectionExam('wrong',true)" ${all.length?'':'disabled'}>全部测试</button></div>`,scrollMode)}
function startWrongCategory(category,scope='all'){let ids=wrongIds(category),list=filterMastery(collectionPool('wrong').filter(q=>ids.includes(q.id)),scope);if(!list.length)return toast('该范围暂无待练错题');if(ensureCollectionScope('wrong','study',{collectionScope:scope,collectionCategory:category}))return;startReviewRecords(wrongReviewRecords(list.map(q=>q.id)),`错题重练 · ${wrongCategoryName(category)}`)}

function getSourcePages(q){if(BANK_RUNTIME)return BANK_RUNTIME.sourcePages(q);return (q?.sourceImages||[q?.sourceImage||1]).map(Number)}
function questionSourceLocation(q){if(q.bankId==='sinotruk_culture_2025_official')return '正式文档 · 原文段落P'+q.sourceParagraphs[0]+'—P'+q.sourceParagraphs.at(-1);let pages=getSourcePages(q);return pages.length?'原题第'+pages.join('、')+'页':'资料出处'}
function renderReviewList(){view='review';let list=reviewQuestions();app(`<div class="section-title"><div><h2>待复核清单</h2><p>本清单只保存在当前浏览器，可导出后反馈题号和资料出处</p></div><button class="btn" onclick="navHome()">返回</button></div>${list.length?`<div class="toolbar"><button class="btn primary" onclick="startReviewStudy()">开始逐题复核</button><button class="btn" onclick="exportReviewReport()">导出复核记录</button></div><div class="review-list">${list.map(q=>`<div class="panel review-item"><h4>${BANK_RUNTIME?esc(BANK_RUNTIME.label(q)):'#'+q.id} · ${esc(questionSourceLocation(q))}</h4><p>${esc(displayText(q.stem))}</p><p>${esc(S.reviewNotes[q.id]?.reason||'未填写原因')} ${esc(S.reviewNotes[q.id]?.note||'')}</p><button class="btn small" onclick="openReviewNote(${q.id})">编辑原因与备注</button><div style="margin-top:8px"><button class="btn small" onclick="reviewOne(${q.id})">打开题目</button> <button class="btn small" onclick="openQuestionSource(${q.id})">查看资料出处</button> <button class="btn small danger" onclick="clearReviewFlag(${q.id})">移出清单</button></div></div>`).join('')}</div>`:`<div class="panel empty"><h2>目前没有待复核题目</h2><p>做题时点“标记待复核”，怀疑的题就会出现在这里。</p><button class="btn primary" onclick="navHome()">返回首页</button></div>`}`)}
function startReviewStudy(){let list=reviewQuestions();if(!list.length)return toast('待复核清单还是空的');startStudySession(list,'待复核题目')}
function toggleReviewFlag(id){S.reviewFlags=S.reviewFlags||{};let flagged=!!S.reviewFlags[id];if(flagged){delete S.reviewFlags[id];delete S.reviewNotes[id]}else S.reviewFlags[id]=Date.now();saveStore();if(view==='question')renderQuestion('preserve');else if(view==='review')renderReviewList();toast(flagged?'已移出待复核清单':'已加入待复核清单')}
