function refreshExamCounts(mode,notify=false){let max=examSetupPool(mode).length,buttons=$$('#countBtns button'),active=buttons.find(b=>b.classList.contains('active'));for(const b of buttons)b.disabled=Number(b.dataset.n)>max;if(!active||active.disabled){let next=[...buttons].filter(b=>!b.disabled).sort((a,b)=>Number(b.dataset.n)-Number(a.dataset.n))[0];buttons.forEach(b=>b.classList.remove('active'));if(next)next.classList.add('active');if(notify)toast(`当前题池最多 ${max} 题，已自动调整题量`)}let info=$('#poolMax');if(info)info.textContent=`当前最多 ${max} 题`}
