app(`<div class="panel exam-setup"><div class="section-title" style="margin-top:0"><div><h2>${title}</h2><p>${contentTopicId()!=='all'?esc(contentTopicName())+' · ':''}选择一种题型进行集中${isExam?'测试':'背诵'}</p></div><button class="btn" onclick="navHome()">返回</button></div>
${!isExam?`<input type="hidden" id="studyMasteryScope" value="${scope}"><div class="notice"><div class="q-actions" role="group" aria-label="背诵范围">${[['all','全部题目'],['unmastered','未掌握题目']].map(([v,t])=>`<button class="btn ${scope===v?'primary':''}" aria-pressed="${scope===v}" onclick="renderSpecialSetup('recite','${type}','${level}','${v}')">${t}${type?'（'+filterMastery(specialPool(type,level),v).length+'）':''}</button>`).join('')}</div><p>未掌握包含未标记、不熟和未掌握；仅跳过已掌握。</p></div>`:''}${!isExam&&(!type||['single','multiple'].includes(type))?thinkBeforeSelectControl():''}<input type="hidden" id="specialType" value="${type}"><div class="field"><label>题型（一次仅选一种）</label><div class="special-type-grid" role="group" aria-label="专项题型">${SPECIAL_TYPES.map(t=>`<button class="btn ${type===t?'active':''}" ${specialPool(t,'enhanced').length?'':'disabled'} aria-pressed="${type===t}" onclick="renderSpecialSetup('${kind}','${t}','${level}','${scope}')">${typeName(t)}</button>`).join('')}</div></div>
${type?`<div class="setup-grid" style="margin-top:18px">${type==='fill'?`<input type="hidden" id="fillLevel" value="${level}"><div class="notice">当前范围基础填空 ${trainingFillPool('enhanced').length}题；高难训练仅使用已审核候选。连续独立答对2次推荐下一级，错答回退一级；查看答案不升级，可自由选择。</div><div class="q-actions">${[['enhanced','基础填空'],['multi','高难多空'],['concept','概念客观填空']].filter(([v])=>trainingFillPool(v).length).map(([v,t])=>`<button class="btn ${level===v?'primary':''}" onclick="renderSpecialSetup('${kind}','fill','${v}','${scope}')">${t} · ${trainingFillPool(v).length}题</button>`).join('')}</div><div class="notice">本级建议复习 ${trainingFillPool(level).filter(q=>S.difficultyProgress?.[q.id]?.review||num(S.wrong[q.id]?.count,0)>0).length}题；等级建议仅供参考，不锁题。</div><button class="btn" onclick="startWeakFill('${level}')">单独复习薄弱题</button>`:''}
${isExam?`<div class="field"><label>题目数量 <span id="poolMax" class="muted">当前最多 ${max} 题</span></label><div class="count-buttons" id="countBtns">${unique.map(n=>`<button class="btn ${n===defaultCount?'active':''}" data-n="${n}" ${n>max?'disabled':''}>${n===max?'全部（'+n+'题）':n+'题'}</button>`).join('')}</div></div><div class="field"><label>考试规则</label><select id="examRule"><option value="normal">普通模式（未答可交卷）</option><option value="strict">严格模式（必须全部作答）</option></select></div>`:`<div class="field"><label>本轮数量（可选）<select id="reciteBatch"><option value="0">全部 ${max}题</option>${[5,10,20].filter(n=>n<max).map(n=>`<option value="${n}">${n}题一组</option>`).join('')}</select></label></div>`}</div>`:'<div class="notice" style="margin-top:18px">请先选择一种题型。</div>'}
<div style="margin-top:18px"><button class="btn primary" ${!type||!max?'disabled':''} onclick="${isExam?'beginSpecialExam()':'startSpecialRecite()'}">开始${title}</button></div></div>`);
$$('#countBtns button').forEach(b=>b.onclick=()=>{if(b.disabled)return;$$('#countBtns button').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
if(isExam&&type&&!$('#countBtns .active:not(:disabled)')){let next=$$('#countBtns button').filter(b=>!b.disabled)[0];next?.classList.add('active')}
