function startWeakFill(level='enhanced',scope='all'){if(!trainingFillPool(level).some(q=>S.difficultyProgress?.[q.id]?.review||S.wrong[q.id]))return toast('本级暂无薄弱题');startFillStudy('sequence',level,scope);if(!session||session.kind!=='fillStudy')return;let items=session.items.filter(i=>S.difficultyProgress?.[i.q.id]?.review||num(S.wrong[i.q.id]?.count,0)>0);if(!items.length)return toast('本级暂无薄弱题');session.items=items;session.masteryPool=[...items];current=0;renderQuestion()}
function startSpecialRecite(chosenScope){
let type=$('#specialType')?.value,level=$('#fillLevel')?.value||'enhanced',scope=chosenScope==='unmastered'?'unmastered':chosenScope==='all'?'all':$('#studyMasteryScope')?.value==='unmastered'?'unmastered':'all';if(!SPECIAL_TYPES.includes(type))return toast('请先选择一种题型');
let batch=Number($('#reciteBatch')?.value||0);if(type==='fill'){startFillStudy('sequence',level,scope,batch);return}
let pool=specialPool(type);startStudySession(batch?filterMastery(pool,scope).slice(0,batch):pool,typeName(type).replace('题','')+'专项背诵',scope);session.mode='special_recite';session.questionType=type;renderQuestion();
}
function beginSpecialExam(presetType=''){
let type=presetType||$('#specialType')?.value,level=type==='fill'?'enhanced':'standard';if(!SPECIAL_TYPES.includes(type))return toast('请先选择一种题型');
if(type==='fill'){beginExam('fill');return}
let pool=specialPool(type),n=Number($('#countBtns .active')?.dataset.n||0);if(!n||n>pool.length)return toast(`当前题池最多 ${pool.length} 题，不能生成所选题量`);
// Whole-bank type practice keeps every original ID, including known duplicate groups.
// Smaller papers retain the shared coverage and duplicate-group avoidance strategy.
let picked=coveragePick(pool,n),used=new Set(picked.map(q=>q.id));
if(picked.length<n)picked.push(...shuffle(pool.filter(q=>!used.has(q.id))).slice(0,n-picked.length));
if(picked.length!==n)return toast('组卷题量异常，已阻止进入考试');
let paperId=makePaperId(),items=applyOptionOrders(buildItems(picked,'study'),paperId);
session={kind:'exam',mode:'special_exam',questionType:type,fillLevel:level,strict:$('#examRule').value==='strict',items,started:Date.now(),title:contentTopicTitle(typeName(type).replace('题','')+'专项模拟',picked),finished:false,rotationRecorded:false,paperId};current=0;initExamTimer();saveSession();renderQuestion();
}

function makePaperId(){return `P${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`}
function beginExam(mode){if(mode!=='fill')return toast('该模式已移除，请使用专项模拟或真实模拟');let n=Number($('#countBtns .active')?.dataset.n||0),choice=$('#fillLevel')?.value||'enhanced',level=['multi','concept'].includes(choice)?'ultra':'enhanced',pool=trainingFillPool(choice);if(!n||n>pool.length){toast(`当前题池最多 ${pool.length} 题，不能生成所选题量`);refreshExamCounts(mode);return}let picked=coveragePick(pool,n);if(picked.length<n){let used=new Set(picked.map(q=>q.id));picked.push(...shuffle(pool.filter(q=>!used.has(q.id))).slice(0,n-picked.length))}let items=buildItems(picked,'fill',0,level);if(items.length!==n){toast('组卷题量异常，已阻止进入考试');return}let paperId=makePaperId();assignFillVariantKeys(items);applyOptionOrders(items,paperId);session={kind:'exam',mode:'special_exam',questionType:'fill',fillLevel:level,strict:$('#examRule').value==='strict',items,started:Date.now(),title:contentTopicTitle(`填空专项模拟 · ${level==='enhanced'?'增强':'标准'}`,picked),finished:false,rotationRecorded:false,paperId};current=0;initExamTimer();saveSession();renderQuestion()}

