function renderRealExamSetup(mode='real'){if(contentTopicId()!=='all')return renderSpecialSetup('exam');if(Q.length&&Q.every(q=>q.type==='fill')){renderSpecialSetup('exam','fill');toast(`当前题库只含填空题，请使用填空专项模拟，可选择全部${Q.length}题`);return;}if(mode==='fillStrong')return renderRealExamSetup('real');view='examSetup';let fillCount=10,total=45,title=isOfficialCultureScope()?'企业文化综合模拟':'真实模拟 Ultra';app(`<div class="panel exam-setup"><div class="section-title" style="margin-top:0"><div><h2>${title}</h2><p>${isOfficialCultureScope()?'固定45题，含单选、多选、判断和精选填空；整题全对计分':'固定45题，客观填空按逐空规则评分；旧55题记录仍可查看'}</p></div><button class="btn" onclick="navHome()">返回</button></div>
<div class="dashboard-grid" style="margin-top:8px"><div class="panel pad"><b>单选题</b><div style="font-size:30px;font-weight:800">15</div></div><div class="panel pad"><b>多选题</b><div style="font-size:30px;font-weight:800">10</div></div><div class="panel pad"><b>判断题</b><div style="font-size:30px;font-weight:800">10</div></div><div class="panel pad"><b>${isOfficialCultureScope()?'精选填空':'增强填空'}</b><div style="font-size:30px;font-weight:800">${fillCount}</div></div></div>
<div class="setup-grid" style="margin-top:18px"><div class="field"><label>试卷总题数</label><div class="notice"><b>${total} 题</b> · 题型数量固定</div></div><div class="field"><label>考试规则</label><select id="realExamRule"><option value="normal">普通模式（未答可交卷）</option><option value="strict">严格模式（必须全部作答）</option></select></div></div>
<div class="notice" style="margin-top:16px">${isOfficialCultureScope()?'正式题库精选51道可填空训练题中选10道，与本卷原题型去重，不额外增加题库总数。':'填空从现有填空池及已核原图的多空候选中按知识点去重选取：3道基础、4道多空、3道概念。题池不足时不会凑数。'}</div>
<div style="margin-top:18px"><button class="btn primary" onclick="beginRealExam('real')">开始${title}</button></div></div>`)}
function beginRealExam(mode='real'){if(isOfficialCultureScope())return beginOfficialCultureExam();if(Q.length&&Q.every(q=>q.type==='fill'))return renderRealExamSetup();
  if(mode==='fillStrong')return toast('真实模拟PLUS仅保留历史复盘，请使用45题Ultra');
  const multiIds=Object.keys(ULTRA_MULTI_BY_ID).map(Number),conceptIds=Object.keys(ULTRA_CONCEPT_BY_ID).map(Number),reserved=new Set([...multiIds,...conceptIds,79,114,116,117,119,210,385,410,421]);
  const used=new Set(),regularBlocked=new Set(reserved);
  const singles=pickRealRegular('single',15,regularBlocked);singles.forEach(q=>{used.add(q.id);regularBlocked.add(q.id)});
  const multiples=pickRealRegular('multiple',10,regularBlocked);multiples.forEach(q=>{used.add(q.id);regularBlocked.add(q.id)});
  const judges=pickRealRegular('judge',10,regularBlocked);judges.forEach(q=>{used.add(q.id);regularBlocked.add(q.id)});
  const multi=coveragePick(Q.filter(q=>ULTRA_MULTI_BY_ID[q.id]),4,used);multi.forEach(q=>used.add(q.id));
  const concept=coveragePick(Q.filter(q=>conceptIds.includes(q.id)),3,used);concept.forEach(q=>used.add(q.id));
  const basic=coveragePick(Q.filter(q=>isFillEligible(q,'enhanced')&&!reserved.has(q.id)&&(resolveFillEntry(q,'enhanced')?.stem.match(/______/g)||[]).length===1),3,used);
  if(singles.length!==15||multiples.length!==10||judges.length!==10||multi.length!==4||concept.length!==3||basic.length!==3){toast('已核验题池不足以生成45题，未创建试卷');return}
  if(BANK_RUNTIME&&BANK_RUNTIME.scopeBankIds().some(n=>![...singles,...multiples,...judges,...basic,...multi,...concept].some(q=>q.bankId===n)))return toast('所选题库无法在45题结构内全部覆盖，请缩小范围或补充所缺题型');let paperId=makePaperId(),items=buildItems([...singles,...multiples,...judges],'study');
  items.push(...buildItems(basic,'fill',0,'enhanced'),...buildItems(multi,'fill',0,'ultra'),...buildItems(concept,'fill',0,'ultra'));
  assignFillVariantKeys(items);applyOptionOrders(items,paperId);
  session={kind:'exam',mode:'real',fillLevel:'enhanced',strict:$('#realExamRule').value==='strict',items,started:Date.now(),title:'真实模拟 Ultra',finished:false,rotationRecorded:false,paperId};
  current=0;view='question';initExamTimer();saveSession();renderQuestion();
}
const ALL_OPEN_CANDIDATES=(window.ULTRA_CANDIDATES||[]).filter(x=>x.autoGrade===false),OPEN_CANDIDATES=ALL_OPEN_CANDIDATES.filter(x=>!BANK_RUNTIME||BANK_RUNTIME.scopeBankIds().includes(x.bankId));
function openCandidate(id){return ALL_OPEN_CANDIDATES.find(x=>x.candidateId===id)}
function renderOpenStudy(filter='all'){
  view='openStudy';let rows=OPEN_CANDIDATES.filter(x=>filter!=='review'||['partial','unmastered'].includes(S.openStudy?.[x.candidateId]?.state)),rated=OPEN_CANDIDATES.filter(x=>['mastered','partial','unmastered'].includes(S.openStudy?.[x.candidateId]?.state));
  let mastered=rated.filter(x=>S.openStudy[x.candidateId].state==='mastered').length;
  app(`<div class="section-title"><div><h2>概念释义与简答训练</h2><p>先独立作答，提交后对照原图依据和要点，再由你自评；系统不把开放回答自动判对</p></div><button class="btn" onclick="navHome()">返回题库</button></div>
  <div class="notice">已完成自评 ${rated.length}/${OPEN_CANDIDATES.length}；其中掌握 ${mastered} 题。${rated.length?`已自评题掌握率 ${Math.round(mastered/rated.length*100)}%`:'尚未自评，不生成正确率。'} 自评记录会随账号同步，也可在设置的“备份与恢复”中导出。</div>
  <div class="q-actions"><button class="btn ${filter==='all'?'primary':''}" onclick="renderOpenStudy('all')">全部题目</button><button class="btn ${filter==='review'?'primary':''}" onclick="renderOpenStudy('review')">需要复习</button></div>
  <div class="review-list">${rows.map(x=>{let r=S.openStudy?.[x.candidateId],label={draft:'未提交',submitted:'待自评',mastered:'已掌握',partial:'部分掌握',unmastered:'未掌握'}[r?.state]||'未开始';return `<div class="panel review-item"><h3>${esc(x.stem)}</h3><p>原题 ${x.sourceQuestionIds.map(id=>BANK_RUNTIME?esc(BANK_RUNTIME.label(ALL_Q.find(q=>q.id===id))):'#'+id).join('、')} · 第 ${x.sourceImages.join('、')} 页 · ${label}</p><button class="btn primary small" onclick="renderOpenQuestion('${x.candidateId}')">${r?'继续':'开始'}</button></div>`}).join('')||'<div class="panel empty">暂无需要复习的简答题。</div>'}</div>`);
}
function renderOpenQuestion(id,scrollMode='question'){let x=openCandidate(id);if(!x)return renderOpenStudy();view='openQuestion';let r=S.openStudy?.[id]||{answer:'',state:'draft'},revealed=r.state!=='draft',snapshot=r.snapshot||{stem:x.stem,standardAnswer:x.standardAnswer,mandatoryPoints:x.rubric?.mandatoryPoints||[],criticalMisconceptions:x.rubric?.criticalMisconceptions||[]};app(`<div class="section-title"><div><h2>概念释义与简答训练</h2><p>原题 ${x.sourceQuestionIds.map(id=>BANK_RUNTIME?esc(BANK_RUNTIME.label(ALL_Q.find(q=>q.id===id))):'#'+id).join('、')} · ${revealed?'已交卷，按要点自评':'作答阶段，参考答案暂不显示'}</p></div><button class="btn" onclick="renderOpenStudy()">返回题目列表</button></div><div class="panel pad open-study-card"><h3 class="question-focus">${esc(snapshot.stem)}</h3><label class="field"><span>我的回答</span><textarea class="transfer-text" rows="7" maxlength="3000" ${revealed?'disabled':''} oninput="setOpenAnswer('${id}',this.value)">${esc(r.answer)}</textarea></label><div class="q-actions">${revealed?`<button class="btn" onclick="openQuestionSource(${x.sourceQuestionIds[0]})">查看原题页</button>`:``}${revealed?'':`<button class="btn primary" onclick="submitOpenAnswer('${id}')">提交后查看参考答案</button>`}</div>${revealed?`<div class="notice open-reference"><b>参考答案</b><p>${esc(snapshot.standardAnswer)}</p><b>自评要点</b><ul>${snapshot.mandatoryPoints.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><b>常见误区</b><ul>${(snapshot.criticalMisconceptions?.length?snapshot.criticalMisconceptions:x.rubric?.criticalMisconceptions||[]).map(p=>`<li>${esc(p)}</li>`).join('')}</ul><p>按要点评估理解：关键概念正确且覆盖要点可选掌握；漏要点选部分掌握；概念混淆选未掌握。准确背诵另到填空模式检验。</p><details><summary>可选：逐点对照（不自动评分）</summary>${snapshot.mandatoryPoints.map(p=>`<label class="rubric-check"><input type="checkbox">${esc(p)}</label>`).join('')}</details></div><div class="q-actions"><button class="btn ${r.state==='mastered'?'primary':''}" onclick="rateOpenAnswer('${id}','mastered')">掌握</button><button class="btn ${r.state==='partial'?'primary':''}" onclick="rateOpenAnswer('${id}','partial')">部分掌握</button><button class="btn ${r.state==='unmastered'?'primary':''}" onclick="rateOpenAnswer('${id}','unmastered')">未掌握</button><button class="btn" onclick="retryOpenAnswer('${id}')">重新作答</button><button class="btn" onclick="nextOpenQuestion('${id}')">下一题</button>${['mastered','partial','unmastered'].includes(r.state)?'<span role="status">自评已保存</span>':''}</div>`:''}</div>`,scrollMode)}
function setOpenAnswer(id,value){if(!openCandidate(id))return;S.openStudy=S.openStudy||{};let r=S.openStudy[id]||{state:'draft',time:Date.now()};if(r.state!=='draft')return;r.answer=String(value).slice(0,3000);r.time=Date.now();S.openStudy[id]=r;queueSave()}
function submitOpenAnswer(id){let x=openCandidate(id),r=S.openStudy?.[id];if(!x||!r?.answer?.trim())return toast('请先填写自己的回答');if(r.state!=='draft')return;r.state='submitted';r.time=Date.now();r.snapshot={stem:x.stem,standardAnswer:x.standardAnswer,mandatoryPoints:[...(x.rubric?.mandatoryPoints||[])],criticalMisconceptions:[...(x.rubric?.criticalMisconceptions||[])]};saveStore();renderOpenQuestion(id,'preserve');exposeSubmittedFeedback()}
function rateOpenAnswer(id,state){let r=S.openStudy?.[id];if(!r||r.state==='draft'||!['mastered','partial','unmastered'].includes(state))return;r.state=state;r.time=Date.now();if(!saveStore())return;renderOpenQuestion(id,'preserve');toast('自评已保存')}
function retryOpenAnswer(id){if(!openCandidate(id))return;S.openStudy[id]={answer:'',state:'draft',time:Date.now(),snapshot:null};saveStore();renderOpenQuestion(id)}

function recordStudyExposure(item){if(session?.kind==='exam'||session?.reviewMode==='original'||item.exposureRecorded)return;let l=S.learning[item.q.id]||(S.learning[item.q.id]=baseLearning());l.totalExposure++;if(item.renderType==='fill')l.fillExposure++;else l.regularExposure++;item.exposureRecorded=true}
function renderQuestion(scrollMode='question'){view='question';if(!session)return navHome(true);if(!session.items.length&&session.masteryPool){app(`<div class="section-title"><h2>${esc(session.title)}</h2><button class="btn" onclick="navHome()">返回题库</button></div>${studyScopeControls()}<div class="panel pad"><h3>本范围内没有未掌握题目</h3><p>已掌握的题仍保留在全部题目中，可以随时切换回来复习。</p><button class="btn primary" onclick="setStudyScope('all')">复习全部题目</button></div>`);return}if(!session.items.length)return navHome(true);session.paperId||=makePaperId();let sheetWasOpen=captureSheetPosition();let item=session.items[current],q=item.q;capturePresentation(item);item.visited=true;recordStudyExposure(item);saveSeen(q.id);let isExam=session.kind==='exam',isFillStudy=session.kind==='fillStudy';if(isFillStudy)item.viewed=true;let recite=!isExam&&!session.reviewMode&&(isFillStudy||session.mode==='special_recite'||session.title==='顺序背题'),reciteVisible=recite&&((!thinkBeforeSelectActive(item)&&S.settings.reciteAnswers==='always')||item.reciteRevealed);let locked=!isExam&&item.checked&&!isFillStudy;let reveal=isFillStudy?!!reciteVisible:!!(reciteVisible||(!isExam&&(item.checked||item.showExplanation)));let ex=explain(q,item.renderType,item.fillLevel,item.fillVariantKey);if(item.presentationSnapshot){ex.answers=itemAnswers(item);if(item.renderType==='fill'&&q.bankId!=='sinotruk_culture_2026')ex.summary=item.presentationSnapshot.why||ex.summary}if(reciteVisible)item.assisted=true;let fav=S.favorites.includes(q.id),flagged=!!S.reviewFlags?.[q.id];let mastery=S.mastery[q.id]||'';app(`<div class="section-title question-session-header"><h2>${esc(session.title)}</h2><div class="q-actions">${!session.finished?`<button class="btn small" onclick="pauseAndSave()">暂停保存，回首页</button>`:''}${session.parentFrame?'<button class="btn small" onclick="returnToPracticeSource()">返回来源</button>':''}${session.finished?'<button class="btn small" onclick="navHome()">返回题库</button>':''}</div></div>
<div class="study-layout"><div class="panel question-card">
<div class="question-focus question-status" aria-label="当前题目信息"><span class="tag ${item.renderType}">${typeName(item.renderType)}</span><span class="question-position">${current+1} / ${session.items.length}</span>${isTimedSession()?`<div class="exam-timebar" title="切到后台或锁屏自动暂停"><span>⏱ 总用时 <b id="examTimer">${formatDuration(liveTotalMs())}</b></span><span>本题 <b id="questionTimer">${formatQTime(liveQuestionMs())}</b></span></div>`:''}</div>
<div class="q-stem">${esc(itemStem(item))}</div>${item.renderType!=='fill'&&!objectiveReady(q)?'<div class="notice danger-notice">此题原文或依据待核验：保留资料查看，暂停新的选择/判断判分，请先看解析中的具体问题。</div>':''}${isFillStudy?(reveal?renderFillStudyAnswer(item):'<div class="notice">答案已隐藏，请先在脑中回忆，再点击查看。</div>'):renderInput(item,locked)}
${!isExam&&!isFillStudy&&reveal?renderImmediateFeedback(item):''}${!isExam?`<div id="practiceEggSlot" class="egg-nudge-slot ${practiceEggHTML?'has-egg':''}">${practiceEggHTML}</div>`:''}${!isFillStudy&&!item.checked&&!reveal?renderConfidence(item):''}${isFillStudy?`<div class="q-actions"><div class="left"><button class="btn primary" onclick="revealReciteAnswer()">${reveal?'隐藏本题答案':'查看本题答案'}</button><button class="btn" onclick="openQuestionSource(${q.id})">${q.bankId==='sinotruk_culture_2025_official'?'查看正式原文':q.type==='fill'?'查看资料出处':'查看原题页'}</button></div><div class="right">${reveal?'':masteryControl(q)}</div></div>`:!isExam?`<div class="q-actions"><div class="left"><button class="btn primary" onclick="checkStudy()" ${item.checked?'disabled':''}>${item.checked?'已判定':'提交答案'}</button><button class="btn" onclick="showExplanation()">${reveal?'解析已展开':'查看解析'}</button><button class="btn" onclick="showAnswer()">直接看答案</button><button class="btn" onclick="openQuestionSource(${q.id})">${q.bankId==='sinotruk_culture_2025_official'?'查看正式原文':q.type==='fill'?'查看资料出处':'查看原题页'}</button></div><div class="right">${reveal?'':masteryControl(q)}</div></div>${(item.checked||reveal)&&session.reviewMode!=='original'?renderConfidence(item):''}`:`<div class="q-actions"><div class="left"><span class="exam-lock-note">考试中隐藏答案、解析和原题截图</span></div><div class="right"><button class="btn" onclick="prevQ()" ${current===0?'disabled':''}>上一题</button><button class="btn primary" onclick="nextQ()">${current===session.items.length-1?'检查/交卷':'下一题'}</button></div></div>`}
<div class="q-head question-secondary-tools"><p class="question-source-id">第 ${current+1}/${session.items.length} 题 · 原题号 ${BANK_RUNTIME?esc(BANK_RUNTIME.label(q)):'#'+q.id}</p><div class="q-meta"><span class="tag ${item.renderType}">${typeName(item.renderType)}</span>${q.tags.map(t=>`<span class="tag">${esc(displayText(t))}</span>`).join('')}${q.technicalVerified?'<span class="tag verified">符号英文已核</span>':''}${q.ocrWarning?'<span class="tag warn">建议核对原图</span>':''}</div><div class="q-head-tools"><button class="btn small ${flagged?'flagged':''}" onclick="openReviewNote(${q.id})">${flagged?'已标待复核':'标记待复核'}</button><button class="btn small ${fav?'good':''}" onclick="toggleFav(${q.id})">${fav?'★ 已收藏':'☆ 收藏'}</button></div></div>
${session.reviewMode?`<div class="review-type-switch" role="group" aria-label="复盘题型"><button class="btn ${session.reviewMode==='presented'?'primary':''}" onclick="setReviewMode('presented')">本场题型</button><button class="btn ${session.reviewMode==='original'?'primary':''}" onclick="setReviewMode('original')">原题题型</button><p class="muted">${session.reviewMode==='original'?'原题仅供对照，不重复计入学习统计。':item.legacyReview?'旧记录未保存呈现快照，安全回退到原题题型。':'按本场实际题型复盘，挖空位置保持不变。'}</p></div>`:''}${session.reviewMode==='presented'&&item.reviewSource?`<div class="notice">本场作答：${esc(answerDisplay(item.reviewSource.userAnswer))}</div>`:''}${session.title==='今日复习'?`<div class="recommendation-reason">本题推荐：${esc(reviewReasons(q).join('、'))}</div>`:''}${questionPreferences(recite)}
${planRecallMarkup(item,reveal)}${reveal?renderExplanation(q,ex,item.checked?item.correct:null,isFillStudy||!isExam):''}
${!isExam?`<div class="q-actions"><div class="left"><button class="btn" onclick="prevQ()" ${current===0?'disabled':''}>上一题</button></div><div class="right"><button class="btn primary" onclick="nextQ()">${current===session.items.length-1?'完成本轮':'下一题'}</button></div></div>`:''}</div>
<aside id="answerPanel" class="panel side answer-panel" data-paper="${session.paperId}"><div class="answer-panel-head"><h3>${isFillStudy?'背诵导航':'答题卡'}</h3><button class="btn small sheet-locate" onclick="locateCurrentSheetQuestion()">定位当前题</button><button class="btn small answer-panel-close" onclick="toggleAnswerPanel(false)" aria-label="关闭题号索引">关闭</button></div><div class="answer-sheet" onscroll="rememberSheetPosition(this)">${session.items.map((x,i)=>sheetItemMarkup(x,i,isFillStudy)).join('')}</div><div style="margin-top:14px" class="muted sheet-progress">${isExam?`已答 ${answeredCount()}/${session.items.length} · 未答 ${session.items.length-answeredCount()}`:isFillStudy?`已看 ${session.items.filter(x=>x.viewed).length}/${session.items.length}`:`已练 ${session.items.filter(x=>x.checked).length}/${session.items.length}`}</div>${sheetLegend()}${isExam?`<div class="side-timing"><span>总用时</span><b id="examTimerSide">${formatDuration(liveTotalMs())}</b></div><button class="btn danger" style="width:100%;margin-top:10px" onclick="submitExam()">交卷</button>`:''}</aside></div>
<div class="sheet-backdrop" onclick="toggleAnswerPanel(false)"></div><nav class="quick-nav" aria-label="快捷翻题"><button class="btn" onclick="prevQ()" ${current===0?'disabled':''}>← 上一题</button><button class="btn index-btn" onclick="toggleAnswerPanel(true)">题号 ${current+1}/${session.items.length}</button><button class="btn primary" onclick="nextQ()">${current===session.items.length-1?(isExam?'检查/交卷':'完成本轮'):'下一题 →'}</button></nav>`,scrollMode);restoreSheetPosition(sheetWasOpen);requestAnimationFrame(()=>{updateTimerUI();let side=$('#examTimerSide');if(side)side.textContent=formatDuration(liveTotalMs())})}
function fillStem(q,type,level='standard',fillVariantKey=''){if(type!=='fill')return displayText(q.stem);return displayText(resolveFillEntry(q,level,fillVariantKey)?.stem||q.stem)}
function renderFillStudyAnswer(item){return `<div class="fill-study-answer"><div class="fill-answer-summary"><span>正确答案</span><b>${esc(itemAnswers(item).join('；'))}</b><small>先根据独立题干在脑中作答，再核对答案和下方的判断依据。</small></div>${masteryControl(item.q)}</div>`}
function renderInput(item,locked){let q=item.q;if(hideStudyOptions(item))return '<div class="notice think-select-prompt"><p>先在脑中回想答案，想好后再显示选项。</p><button class="btn primary" onclick="revealStudyOptions()">显示选项，开始作答</button></div>';if(item.renderType==='fill'){let spec=item.presentationSnapshot?.blankConfig?.gradeSpec||resolveFillEntry(q,item.fillLevel,item.fillVariantKey)?.gradeSpec;if(spec){let legacy=typeof item.answer==='string'?`<div class="notice">旧版单框答案（保留原文，不自动拆空）：${esc(item.answer)}</div>`:'',values=Array.isArray(item.answer)?item.answer:spec.blanks.map(()=>''),fields=spec.blanks.map((_,i)=>`<label class="ultra-blank">第 ${i+1} 空${item.retainedBlanks?.includes(i)?'<small>本轮已保留</small>':''}<input type="text" inputmode="text" autocomplete="off" ${locked||item.retainedBlanks?.includes(i)?'disabled':''} value="${esc(values[i]||'')}" oninput="setBlankAnswer(${i},this.value)" onkeydown="blankEnter(event,${i})" enterkeyhint="${i===spec.blanks.length-1?'done':'next'}" aria-label="第 ${i+1} 空答案"></label>`).join('');return `${legacy}<div class="ultra-blank-grid">${fields}</div><p class="muted">每空单独填写，按顺序判分；标点和空格差异不扣分，关键字须准确。每空结果单独保留，整题全对才记为答对。</p>`}let v=Array.isArray(item.answer)?item.answer.join('、'):(item.answer||'');return `<div class="field fill-box"><textarea ${locked?'disabled':''} placeholder="请输入答案；多答案可用顿号、逗号分隔" oninput="setAnswer(this.value)">${esc(displayText(v))}</textarea><div class="fill-hint">本题题干已经人工复核，可脱离原选择题选项独立作答。</div></div>`}let multiple=q.type==='multiple',options=item.optionOrder||q.options;return `<div class="options">${options.map((o,i)=>{let sel=multiple?Array.isArray(item.answer)&&item.answer.includes(o):item.answer===o;let cls=sel?'selected':'';if(locked){let isC=q.answers.some(a=>cleanAns(a)===cleanAns(o));if(isC)cls+=' correct';else if(sel)cls+=' wrong'}return `<button class="option ${cls}" aria-pressed="${!!sel}" onclick="chooseOption(${i})" ${locked?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(displayText(o))}</span></button>`}).join('')}</div>`}
function setAnswer(v){session.items[current].answer=v;queuePracticeSave();if(isActiveExam())queueSaveSession();else queueSave()}
function setBlankAnswer(index,value){let item=session?.items?.[current],spec=item?.presentationSnapshot?.blankConfig?.gradeSpec||resolveFillEntry(item?.q,item?.fillLevel,item?.fillVariantKey)?.gradeSpec;if(item?.retainedBlanks?.includes(index)||item?.checked)return;if(!spec||!Number.isInteger(index)||index<0||index>=spec.blanks.length)return;if(!Array.isArray(item.answer)||item.answer.length!==spec.blanks.length)item.answer=spec.blanks.map(()=>'');item.answer[index]=String(value).slice(0,300);queuePracticeSave();if(isActiveExam())queueSaveSession();else queueSave()}
function queueSaveSession(){if(saveDebounceTimer)clearTimeout(saveDebounceTimer);saveDebounceTimer=setTimeout(()=>saveSession(),350)}
// Keep the question and manual answer-sheet scroll position intact on selection.
function updateOptionSelection(item){const options=$$('.options .option');if(!options.length||!options.every(b=>b.classList&&b.setAttribute)){renderQuestion('preserve');return}const order=item.optionOrder||item.q.options;options.forEach((button,i)=>{const selected=item.q.type==='multiple'?Array.isArray(item.answer)&&item.answer.includes(order[i]):item.answer===order[i];button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});const cell=$('.answer-sheet')?.children?.[current];if(cell)cell.outerHTML=sheetItemMarkup(item,current,false);const progress=$('.sheet-progress');if(progress&&session.kind==='exam')progress.textContent=`已答 ${answeredCount()}/${session.items.length} · 未答 ${session.items.length-answeredCount()}`;}
function chooseOption(i){let item=session.items[current];if(item.checked&&session.kind!=='exam'||hideStudyOptions(item))return;let o=(item.optionOrder||item.q.options)[i];if(o===undefined)return;if(item.q.type==='multiple'){let a=Array.isArray(item.answer)?[...item.answer]:[];a=a.includes(o)?a.filter(x=>x!==o):[...a,o];item.answer=a}else item.answer=o;updateOptionSelection(item);if(isActiveExam())saveSession();else{queueSave();queuePracticeSave()}}
function baseLearning(){return {attempts:0,correct:0,wrong:0,streak:0,totalMs:0,timedAttempts:0,assistedCorrect:0,lowConfidenceCorrect:0,totalExposure:0,regularExposure:0,fillExposure:0,lastSeenRound:0,last:0,due:0}}
function syncLowConfidenceContribution(item){let low=item.confidencePhase==='before'&&!item.assisted&&!!item.correct&&!!item.attemptRecorded&&['hesitant','guess'].includes(item.confidence),previous=!!item.lowConfidenceContribution,x=S.learning[item.q.id]||baseLearning();if(low!==previous){x.lowConfidenceCorrect=Math.max(0,num(x.lowConfidenceCorrect,0)+(low?1:-1));if(low)x.due=Math.min(x.due||Infinity,Date.now()+86400000)}item.lowConfidenceContribution=low;S.learning[item.q.id]=x}
const SCORE_EGGS={score100:{quote:'春风得意马蹄疾，一日看尽长安花。',verdict:'满分，今天这套没给你留下什么机会。'},score90:{quote:'会当凌绝顶，一览众山小。',verdict:'这套打得很稳，错题收一下就更漂亮了。'},score80:{quote:'行百里者半九十。',verdict:'离90分不远，回头把这几道错题收了。'},score70:{quote:'知不足，然后能自反也；知困，然后能自强也。',verdict:'方向是对的，再把薄弱题型补一轮。'},score60:{quote:'路漫漫其修远兮，吾将上下而求索。',verdict:'及格是及格了，就是落地时擦了下起落架。'},scoreLow:{quote:'胜败兵家事不期。',verdict:'这套题对你实施了一次精准打击，先收错题。'},score40:{quote:'知耻近乎勇。',verdict:'先别急着再开一套，把今天的错题狠狠干明白。'},score20:{quote:'不积跬步，无以至千里。',verdict:'下降空间不大了；换个角度，后面基本都是上涨空间。'}};
