function scoreEggId(score){return score===100?'score100':score>=90?'score90':score>=80?'score80':score>=70?'score70':score>=60?'score60':score>=40?'scoreLow':score>=20?'score40':'score20'}
function closeEasterEgg(){$('#eggModal')?.classList.add('hidden');practiceEggHTML='';$('#eggNudge')?.remove();if(eggNudgeTimer)clearTimeout(eggNudgeTimer)}
function pickEggCopy(id,random=Math.random){let pool=EGG_TEXT_POOLS[id]||[],e=S.easterEggs||(S.easterEggs=emptyEggState()),recent=new Set(e.recentCopyKeys||[]),eligible=pool.filter(x=>!recent.has(x.key)&&(!x.rare||random()<.08));if(!eligible.length)eligible=pool.filter(x=>!x.rare);if(!eligible.length)eligible=pool;return eligible[Math.floor(random()*eligible.length)]||{key:`${id}-fallback`,quote:'',verdict:EGG_CATALOG[id]?.name||''}}
function canShowEgg(id,force=false){let e=S.easterEggs||(S.easterEggs=emptyEggState()),now=Date.now(),last=num(e.lastShown[id],0);return !!EGG_CATALOG[id]&&(force||(now-eggRuntime.lastAt>=45000&&now-last>=10*60000))}
function commitShownEggs(ids,copyKeys,title=''){let e=S.easterEggs||(S.easterEggs=emptyEggState()),now=Date.now();for(const id of ids){e.discovered=[...new Set([...(e.discovered||[]),id])];e.lastShown[id]=now;e.recent=[...(e.recent||[]).filter(x=>x!==id),id].slice(-8)}e.recentCopyKeys=[...(e.recentCopyKeys||[]),...copyKeys].slice(-12);if(title){e.titles=[...new Set([...(e.titles||[]),title])];e.currentTitle=title}eggRuntime.lastAt=now;saveStore()}
function showEasterEgg(id,data='',force=false,extras=[],title=''){if(S.settings.eggMuted)return false;if(!canShowEgg(id,force))return false;if(view==='question'&&session?.kind!=='exam')return showPracticeEgg(id,data,title);let body=$('#eggBody'),modal=$('#eggModal');if(!body||!modal)return false;let main=pickEggCopy(id),visibleExtras=consolidateEggCandidates(extras).filter(x=>x!==id).slice(0,2),extraCopies=visibleExtras.map(x=>({id:x,copy:pickEggCopy(x)})),meta=EGG_CATALOG[id];body.innerHTML=`<div class="egg-content"><div class="egg-icon">${meta.icon}</div>${main.quote?`<blockquote>${esc(main.quote)}</blockquote>`:''}<div class="egg-verdict">${esc(main.verdict)}</div>${data?`<div class="egg-data">${esc(data)}</div>`:''}${extraCopies.length||title?`<div class="egg-extra"><b>本场额外发现</b>${extraCopies.map(x=>`<span>${EGG_CATALOG[x.id].icon} ${esc(EGG_CATALOG[x.id].name)}</span>`).join('')}${title?`<span>👑 新称号：${esc(title)}</span>`:''}</div>`:''}</div>`;modal.classList.remove('hidden');commitShownEggs([id,...visibleExtras,title?'title':''].filter(Boolean),[main.key,...extraCopies.map(x=>x.copy.key)],title);return true}
function eggFamily(id){return id.startsWith('streak')?'streak':id.startsWith('wrong')?'wrong':id.startsWith('repeat')?'repeat':id}
function consolidateEggCandidates(ids=[]){let rank={streak10:10,streak20:20,wrong3:3,wrong5:5,wrong10:10,repeat3:3,repeat5:5},best=new Map;for(const id of ids){let f=eggFamily(id),old=best.get(f);if(!old||(rank[id]||0)>(rank[old]||0))best.set(f,id)}return [...best.values()]}
function eligibleTitle(){let e=S.easterEggs||(S.easterEggs=emptyEggState()),ag=S.aggregateStats||emptyAggregate(),seen=Object.keys(S.seen||{}).length,corrected=Object.values(S.wrong||{}).filter(x=>x.corrected).length,scores=(S.history||[]).slice(0,5).map(x=>x.score),title='初窥门径';if((ag.totalAnswers||0)>=100)title='渐入佳境';if(scores.filter(x=>x>=90).length>=3)title='胸有成竹';if((ag.totalAnswers||0)>=500&&corrected>=20)title='炉火纯青';if(seen>=400&&scores.length>=5&&scores.every(x=>x>=90))title='登峰造极';if(seen>=480&&scores.length>=5&&scores.every(x=>x>=95)&&corrected>=40)title='神人降临';return title!=='初窥门径'&&!(e.titles||[]).includes(title)?title:''}
function checkTitleUnlocks(){let title=eligibleTitle();if(!title)return '';if(session?.kind==='exam'&&session.finished){session._eggTitleCandidate=title;return title}return showEasterEgg('title',`累计作答 ${S.aggregateStats?.totalAnswers||0} 题次`,false,[],title)?title:''}
function processAnswerEgg(item,correct,assisted,beforeWrong){if(assisted)return;let e=S.easterEggs||(S.easterEggs=emptyEggState());e.answerStreak=correct?{correct:num(e.answerStreak?.correct,0)+1,wrong:0}:{correct:0,wrong:num(e.answerStreak?.wrong,0)+1};let s=correct?e.answerStreak.correct:e.answerStreak.wrong,id='',w=S.wrong[item.q.id]||{},repeats=w.wrongTotal||0;if(correct&&(s===10||s===20))id=s===20?'streak20':'streak10';if(!correct&&[3,5,10].includes(s))id=s===10?'wrong10':s===5?'wrong5':'wrong3';if(!correct&&!id&&(repeats===3||repeats===5))id=repeats===5?'repeat5':'repeat3';if(correct&&beforeWrong>=3&&(w.corrected||w.independentCorrectStreak>=2))id='corrected';if(session?.kind==='exam'&&session.finished){if(id)session._eggCandidates=[...(session._eggCandidates||[]),id];checkTitleUnlocks();return}if(id)showEasterEgg(id,id.startsWith('repeat')?`本题累计答错 ${repeats} 次`:`当前连续${correct?'答对':'答错'} ${s} 题`);checkTitleUnlocks();maybeLateNight()}
function maybeLateNight(){let h=window.BEIJING_CLOCK?.parts().hour??new Date(Date.now()+8*3600000).getUTCHours(),e=S.easterEggs||(S.easterEggs=emptyEggState()),now=Date.now();if((h>=23||h<3)&&now-num(e.lastNightAt,0)>7*86400000&&Math.random()<.08&&showEasterEgg('lateNight')){e.lastNightAt=now;saveStore()}}
function renderEggAtlas(returnTo='settings'){let e=S.easterEggs||(S.easterEggs=emptyEggState()),got=new Set(e.discovered||[]),notes={score100:'满分表现',score90:'高分表现',score80:'接近高分',score70:'继续补强',score60:'低空过线',scoreLow:'低分复盘',score40:'重点补弱',score20:'重新起步',streak10:'连续答对',streak20:'长连对',wrong3:'连续答错',wrong5:'连错提醒',wrong10:'暂停乱答',repeat3:'同题反复错',repeat5:'顽固错题',corrected:'错题纠正',improved:'成绩进步',comeback:'后程逆转',rapidGuess:'过快低正确率',lateNight:'深夜学习提醒',title:'称号解锁'},cards=Object.entries(EGG_CATALOG).map(([id,x])=>`<div class="egg-entry ${got.has(id)?'':'locked'}"><b>${got.has(id)?x.icon+' '+esc(x.name):'？？？'}</b><small>${got.has(id)?esc(notes[id]||'学习事件'):'继续学习解锁'}</small></div>`).join('');app(`<div class="section-title"><div><h2>彩蛋图鉴</h2><p>已发现 ${got.size} / ${Object.keys(EGG_CATALOG).length} · 当前称号：${esc(e.currentTitle||'初窥门径')}</p></div><button class="btn" onclick="returnFromEggAtlas('${esc(returnTo)}')">返回</button></div><div class="egg-atlas">${cards}</div>`)}
function returnFromEggAtlas(where='settings'){if(where==='settings'){renderHome();openSettings()}else if(where==='history')renderHistory();else navHome()}
function updateWrongRecord(item,correct,assisted){let id=item.q.id,w=S.wrong[id]||{count:0,wrongTotal:0,wrongStreak:0,lastWrong:0,lastCorrect:0,independentCorrectStreak:0,assistedCorrect:0,recentResult:'',corrected:false},now=Date.now();if(!correct){w.lastPresentation=capturePresentation(item);w.lastUserAnswer=structuredClone(item.answer);w.count=Math.max(1,w.count||0);w.wrongTotal++;w.wrongStreak++;w.lastWrong=now;w.independentCorrectStreak=0;w.recentResult='wrong';w.corrected=false}else if(assisted){w.assistedCorrect++;w.lastCorrect=now;w.independentCorrectStreak=0;w.recentResult='assistedCorrect'}else{w.lastCorrect=now;w.wrongStreak=0;w.independentCorrectStreak++;w.recentResult='independentCorrect';if(w.count>0&&w.independentCorrectStreak>=2){w.count=0;w.corrected=true}}if(w.wrongTotal||w.count||w.corrected)S.wrong[id]=w}
function recordAggregateAttempt(item,correct){let a=S.aggregateStats||(S.aggregateStats=emptyAggregate()),type=typeName(item.renderType),ms=num(item.timeMs,0),q=item.q;a.totalAnswers++;a.totalCorrect+=correct?1:0;if(ms>0)a.totalStudyMs+=ms;let t=a.byType[type]||(a.byType[type]={attempts:0,correct:0,totalMs:0});t.attempts++;t.correct+=correct?1:0;t.totalMs+=ms;let p=a.byQuestion[q.id]||(a.byQuestion[q.id]={attempts:0,correct:0,wrong:0,totalMs:0});p.attempts++;p.correct+=correct?1:0;p.wrong+=correct?0:1;p.totalMs+=ms;for(const tag of q.tags||[]){let z=a.byTag[tag]||(a.byTag[tag]={attempts:0,correct:0,totalMs:0});z.attempts++;z.correct+=correct?1:0;z.totalMs+=ms}let week=new Date().toISOString().slice(0,10),ws=a.weeks[week]||(a.weeks[week]={attempts:0,correct:0,totalMs:0});ws.attempts++;ws.correct+=correct?1:0;ws.totalMs+=ms}
function sanitizeDifficultyProgress(raw){let out={};if(!raw||typeof raw!=='object')return out;for(let q of ALL_Q){let r=raw[q.id];if(r&&typeof r==='object')out[q.id]={level:Math.floor(num(r.level,0,2)),streak:Math.floor(num(r.streak,0,9999)),review:!!r.review,knowledgeKey:String(r.knowledgeKey||'Q'+q.id).slice(0,100)}}return out}
function recordDifficulty(item,correct,assisted){let ids=itemGradeSpec(item)?.sourceQuestionIds||[item.q.id];S.difficultyProgress=S.difficultyProgress||{};for(let id of ids){let p=S.difficultyProgress[id]||{level:0,streak:0,review:false,knowledgeKey:itemGradeSpec(item)?.knowledgeKey||'Q'+id};let level=ULTRA_CONCEPT_BY_ID[item.q.id]&&item.fillLevel==='ultra'?2:item.fillLevel==='ultra'?1:0;if(!correct){p.level=Math.max(0,p.level-1);p.streak=0;p.review=true}else if(assisted){p.streak=0;p.review=true}else if(level>=p.level){p.streak++;p.review=false;if(p.streak>=2){p.level=Math.min(2,p.level+1);p.streak=0}}S.difficultyProgress[id]=p}}
function updateLearning(item,correct,assisted=false){if(item.renderType!=='fill'&&!objectiveReady(item.q))return false;if(item.attemptRecorded)return false;recordDifficulty(item,correct,assisted);let id=item.q.id;delete S.pendingPractice[id];let x=S.learning[id]||baseLearning(),now=Date.now(),ms=num(item.timeMs,0),beforeWrong=num(S.wrong[id]?.wrongTotal,0);x.attempts++;x.correct+=correct?1:0;x.wrong+=correct?0:1;x.streak=correct&&!assisted?x.streak+1:0;if(ms>0){x.totalMs+=ms;x.timedAttempts++}if(correct&&assisted)x.assistedCorrect++;x.last=now;let days=!correct?1:assisted?1:Math.min(30,Math.max(1,2**Math.min(5,x.streak-1)));x.due=now+days*86400000;S.learning[id]=x;item.attemptRecorded=true;syncLowConfidenceContribution(item);item.assistedResult=!!(correct&&assisted);updateWrongRecord(item,correct,assisted);recordAggregateAttempt(item,correct);recordPlanAttempt(item,correct?(assisted?'assisted':'remembered'):'again');processAnswerEgg(item,correct,assisted,beforeWrong);return true}
function recordPlanAttempt(item,rating){const id=(session?.paperId||makePaperId())+'_q'+item.q.id;window.STUDY_PLANS?.recordQuestion(item.q,rating,id);item.planRecorded=true;}
function planRecallMarkup(item,reveal){if(!session?.planId||!reveal||item.planRecorded)return '';return `<div class="notice plan-recall"><b>这次自己想起来了吗？</b><p>回想后再核对答案，自评只调整计划，不计入考试成绩。</p><div class="q-actions"><button class="btn primary" onclick="ratePlanRecall('remembered')">独立想起了</button><button class="btn" onclick="ratePlanRecall('assisted')">看提示才想起</button><button class="btn" onclick="ratePlanRecall('again')">还没记住</button></div></div>`;}
function ratePlanRecall(rating){const item=session?.items?.[current];if(!item||item.planRecorded||!['remembered','assisted','again'].includes(rating)||!(item.checked||item.showExplanation||item.reciteRevealed))return;recordPlanAttempt(item,rating);if(!saveStore())return;persistPractice();renderQuestion('preserve');toast('已记录，下一次复习已调整');}
function checkStudy(){let item=session.items[current];if(item.renderType!=='fill'&&!objectiveReady(item.q)){item.showExplanation=true;renderQuestion('preserve');return toast('本题原始依据待核验，仅供查看，不记录对错')}if(item.checked||item.attemptRecorded)return toast('本题本轮已记录');if(!hasAnsweredValue(item.answer)){toast(item.renderType==='fill'?'请先填写答案':'先选一个答案');return}if(S.settings.confidenceRequired&&!item.assisted&&!item.confidence){toast('请在提交前选择信心度');return}flushExamTimer();session._activeSince=null;item.correct=answerCorrect(item,item.answer);item.blankResults=gradeItem(item,item.answer)?.blankResults||null;item.checked=true;updateLearning(item,item.correct,!!item.assisted);saveStore();item.showExplanation=true;renderQuestion('preserve');persistPractice();exposeSubmittedFeedback()}
function showExplanation(){let item=session.items[current];item.showExplanation=true;if(!item.checked)item.assisted=true;if(isActiveExam())saveSession();else queueSave();renderQuestion('preserve');exposeSubmittedFeedback()}
function showAnswer(){if(isActiveExam())return;let item=session.items[current];if(session.kind==='fillStudy'||session.mode==='special_recite'){revealReciteAnswer();return}if(!item.checked){item.assisted=true;item.revealed=true}if(item.renderType==='fill'){let spec=itemGradeSpec(item);item.answer=spec?spec.blanks.map(b=>b.canonical):itemAnswers(item).join('、');}else item.answer=item.q.type==='multiple'?[...item.q.answers]:item.q.answers[0];item.showExplanation=true;if(isActiveExam())saveSession();else queueSave();renderQuestion('preserve');exposeSubmittedFeedback()}
function renderConfidence(item){if(item.retainedBlanks&&!item.checked)return '<p class="muted">已看答案后的辅助补练；提交后再记录本轮理解。</p>';if(item.checked||item.showExplanation||item.assisted)return `<div class="confidence-box"><span>核对后理解：</span>${[['clear','已理解'],['review','还需复习']].map(([v,t])=>`<button class="btn small ${S.learning[item.q.id]?.understanding===v?'good':''}" onclick="setUnderstanding('${v}')">${t}</button>`).join('')}<small>自评不改变成绩或独立掌握证据。</small></div>`;return `<details class="pre-confidence" ${item.confidence||S.settings.confidenceRequired?'open':''}><summary>作答前信心${item.confidence?'：'+({sure:'确定会',hesitant:'有点犹豫',guess:'蒙的'}[item.confidence]):'（可选）'}</summary><div class="confidence-box">${[['sure','确定会'],['hesitant','有点犹豫'],['guess','蒙的']].map(([v,t])=>`<button class="btn small ${item.confidence===v?'good':''}" aria-pressed="${item.confidence===v}" onclick="setConfidence('${v}')">${t}</button>`).join('')}</div></details>`}

function setConfidence(v){let item=session?.items[current];if(!item||item.checked||item.showExplanation||item.assisted||!['sure','hesitant','guess'].includes(v))return;item.confidence=v;item.confidencePhase='before';if(isActiveExam())saveSession(false);else saveStore();renderQuestion('preserve')}

function sourceLinks(q){const seen=new Set(),refs=[...(q.sourceReferences||[]),...(objectiveAnalysis(q)?.references||[])].filter(r=>/^https:\/\/[^\s]+$/.test(r.url)&&!seen.has(r.url)&&seen.add(r.url));return refs.length?`<details class="research-sources"><summary>资料依据与支持范围（${refs.length}项）</summary>${refs.map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a><small>${esc(r.date||'未标日期')}${r.support?' · '+esc(r.support):''}</small></p>`).join('')}</details>`:''}
function renderLibraryConnections(q){const a=objectiveAnalysis(q),bank=q.bankId||'hos_2026',rows=(a?.connections||[]).map(c=>({...c,q:ALL_Q.find(target=>(target.bankId||'hos_2026')===bank&&(target.sourceQuestionId||target.id)===c.questionId)})).filter(c=>c.q&&c.q.id!==q.id);if(!rows.length)return '';const reasons=[...new Set(rows.map(c=>c.reason))];return `<details class="library-connections"><summary>把前后知识连起来看 · ${rows.length}道相关题</summary>${reasons.map(reason=>`<p>${esc(reason)}</p>`).join('')}<ul>${rows.map(c=>`<li><button class="btn small" onclick="reviewOne(${c.q.id})">${esc(c.q.originalLabel||'原题'+(c.q.sourceQuestionId||c.q.id))} · ${esc(displayText(c.q.stem).slice(0,100))}</button><small>${objectiveReady(c.q)?'对照要点：'+esc(c.q.answers.join('；')):'待核验，仅供原文资料对照'}</small></li>`).join('')}</ul><small class="muted">相关题用于帮助理解同一考点，具体条件仍以各题为准；打开后可返回原练习。</small></details>`}

