function renderStructuredExplanation(q,ex,correct,hideAnswer){const a=ex.analysis,pending=a.status!=='ready',judge=q.type==='judge';return `<div class="explanation structured-explanation">${pending?'<div class="notice danger-notice"><b>待核验 · 暂停新的自动判分</b><p>下方保留原题参考答案与资料缺口，不作为已经确认的标准结论。</p></div>':''}${hideAnswer?'':`<div class="answer-box"><b>${pending?'原题资料对照':correct===true?'✓ 回答正确':correct===false?'✗ 回答错误':'题目解析'}</b><div>${pending?'原题参考答案':'正确答案'}：${esc(ex.answers.join('；'))}</div></div>`}<h3>考点</h3><div class="analysis-block">${esc(a.topic)}</div><h3>${judge?(q.answers[0]==='对'?'为什么对':'错在哪里'):'选择依据'}</h3><div class="analysis-block">${esc(a.why)}</div>${judge&&ex.correction?`<h3>${pending?'改写建议与待核验内容':'正确表述'}</h3><div class="analysis-block correction-block">${esc(ex.correction)}</div>`:''}${!judge?`<h3>逐项辨析</h3><ul class="option-analysis analysis-block">${ex.opts.map(x=>`<li class="${pending?'source-uncertain':x.ok?'should-select':'should-skip'}"><b>${pending?(x.ok?'原题标注：选中':'原题标注：未选'):(x.ok?'本题应选':'本题不选')} · ${esc(x.text)}</b><span>${esc(x.reason)}</span></li>`).join('')}</ul>`:''}${renderLibraryConnections(q)}${sourceLinks(q)}${a.sourceKind==='official_document'?`<details class="source-note"><summary>正式题库来源与口径</summary><p>来源：${esc(a.sourceDocument)} · ${esc(q.originalLabel)} · 原文段落P${q.sourceParagraphs[0]}起。解析核对于${esc(a.reviewedAt)}。历史数量、相对时间和会议事项按所供2025题库口径理解。</p></details>`:''}${a.sourceKind==='original_bank'?`<details class="source-note"><summary>解析依据与适用范围</summary><p>依据：原题第${esc((a.sourcePages||[]).join('、'))}页及题库答案；解析整理于${esc(a.reviewedAt)}。厂内制度与参数仅按原题口径，现行版本未另获确认。${q.sourceNote?esc(q.sourceNote):''}</p></details>`:''}</div>`}
