let oldRecent=S.recentSessions;forgetActivity(target);S.lastSession=null;if(!saveStore()){S.recentSessions=oldRecent;S.lastSession=oldSnapshot;session=oldSession;current=oldCurrent;if(isTimedSession()){resumeExamTimer();startTimerTicker()}return}document.body.classList.remove('sheet-open');$('#submitConfirm')?.close?.();renderHome();toast('已放弃未完成考试，历史记录保留');
