// Bounded LCS highlights missing, extra and substituted characters. Never changes grading.
function textDifference(actual,expected){let a=Array.from(String(actual||'').normalize('NFKC')).slice(0,300),b=Array.from(String(expected||'').normalize('NFKC')).slice(0,300),dp=Array.from({length:a.length+1},()=>new Uint16Array(b.length+1));for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i][j]=a[i]===b[j]?1+dp[i+1][j+1]:Math.max(dp[i+1][j],dp[i][j+1]);let i=0,j=0,typed='',target='';while(i<a.length||j<b.length){if(i<a.length&&j<b.length&&a[i]===b[j]){typed+=esc(a[i++]);target+=esc(b[j++])}else if(i<a.length&&(j===b.length||dp[i+1][j]>=dp[i][j+1]))typed+='<del>'+esc(a[i++])+'</del>';else target+='<ins>'+esc(b[j++])+'</ins>'}return {typed:typed||'（空白）',target:target||'（空白）'}}
function renderBlankFeedback(item){let rows=item.blankResults||gradeItem(item,item.answer)?.blankResults||[],answers=itemAnswers(item),values=Array.isArray(item.answer)?item.answer:[],n=rows.filter(r=>r.correct).length;return `<div class="blank-feedback"><b>逐空核对 ${n}/${rows.length} 空正确${n&&n<rows.length?' · 已答对的空保留成果，整题须全对':''}</b>${rows.map((r,i)=>{let diff=textDifference(values[i],answers[i]);return `<div class="blank-feedback-row ${r.correct?'ok':'bad'}"><strong>第${i+1}空 ${r.correct?'✓ 正确':'✗ 需改正'}</strong>${r.correct?`<p>${esc(values[i])}</p>`:`<p>填写：${diff.typed}</p><p>标准：${diff.target}</p><small>删除线为多写或写错的字，下划线为缺少或应替换的字；词序按题目空位核对。</small>`}</div>`}).join('')}<small>差异标记用于复习，判分仍按原有严格逐空规则。</small>${n<rows.length?`<button class="btn small" onclick="retryIncorrectBlanks()">只重填错空（辅助练习）</button>`:''}</div>`}
