function highlightSearch(text,query){let source=String(text),needle=normalizeSearchText(query).compact;if(!needle)return esc(source);let units=[],map=[];for(let i=0;i<source.length;){let c=String.fromCodePoint(source.codePointAt(i)),norm=c.normalize('NFKC').toLowerCase();for(const n of norm)if(!/\s/.test(n)){units.push(n);map.push([i,i+c.length])}i+=c.length}let hay=units.join(''),at=hay.indexOf(needle);if(at<0)return esc(source);let start=map[at]?.[0],end=map[at+Array.from(needle).length-1]?.[1];return start==null||end==null?esc(source):esc(source.slice(0,start))+'<mark>'+esc(source.slice(start,end))+'</mark>'+esc(source.slice(end))}
function scopedAggregate(history){let byQuestion=S.aggregateStats?.byQuestion||{},rows=Q.map(q=>byQuestion[q.id]).filter(Boolean);return {totalExams:history.length,recentScores:history.slice(0,20).map(x=>x.score),highestScore:history.length?Math.max(...history.map(x=>x.score)):0,totalStudyMs:rows.reduce((n,x)=>n+num(x.totalMs,0),0)}}
function scopedTagStats(){let map={};for(let q of Q){let x=S.aggregateStats?.byQuestion?.[q.id];if(!x)continue;for(let tag of q.tags){let z=map[tag]||(map[tag]={n:0,correct:0,ms:0});z.n+=num(x.attempts,0);z.correct+=num(x.correct,0);z.ms+=num(x.totalMs,0)}}return Object.entries(map).map(([tag,z])=>({...z,tag,wrong:z.n-z.correct,rate:z.n?z.correct/z.n:0,wrongRate:z.n?(z.n-z.correct)/z.n:0})).sort((a,b)=>a.rate-b.rate||b.n-a.n)}
