 closeEasterEgg();practiceEggHTML=`<div id="eggNudge" class="egg-nudge" role="status"><span>${meta.icon} ${esc(copy.verdict)}${data?` <small>${esc(data)}</small>`:''}</span><button type="button" aria-label="关闭彩蛋提示" onclick="closeEasterEgg()">×</button></div>`;
