// Recent activities are separate from navigation: browsing a list cannot replace a paper.
function activityId(kind,snap){return String(kind==='exam'?snap?.paperId:snap?.session?.paperId||'');}
function sanitizeRecentSessions(rows){if(!Array.isArray(rows))return [];let seen=new Set(),counts=new Map();return rows.filter(x=>x&&['exam','practice'].includes(x.kind)&&typeof x.id==='string'&&x.id.length<=80&&x.id&&x.id===activityId(x.kind,x.snapshot)&&!seen.has(x.id)&&seen.add(x.id)&&typeof x.scopeKey==='string'&&/^[a-z0-9_|-]{1,180}$/.test(x.scopeKey)&&Number.isFinite(x.time)&&x.time>=0&&x.snapshot&&typeof x.snapshot==='object'&&(x.kind==='exam'?compatibleSessionSchema(x.snapshot):x.snapshot.version===1)).sort((a,b)=>b.time-a.time).filter(x=>{let count=counts.get(x.scopeKey)||0;counts.set(x.scopeKey,count+1);return count<2}).slice(0,128);}

function rememberActivity(kind,snapshot){const id=activityId(kind,snapshot);if(!id)return;const row={id,kind,scopeKey:BANK_RUNTIME?.ctx?.scopeKey||'hos_2026',time:Date.now(),snapshot:structuredClone(snapshot)};S.recentSessions=sanitizeRecentSessions([row,...(S.recentSessions||[]).filter(x=>x.id!==id)]);S.recentSessionsMigrated=true;}
function forgetActivity(id){if(id)S.recentSessions=(S.recentSessions||[]).filter(x=>x.id!==id);}
function migrateRecentSessions(){if(S.recentSessionsMigrated)return;let p=readPracticeSnapshot();if(S.lastSession&&!S.lastSession.paperId)S.lastSession.paperId=makePaperId();if(p&&!p.session.paperId)p.session.paperId=makePaperId();if(S.lastSession)rememberActivity('exam',S.lastSession);if(p)rememberActivity('practice',{...p,session:encodePracticeSession(p.session)});S.recentSessionsMigrated=true;saveStore();}
function recentSessionsMarkup(){const scope=BANK_RUNTIME?.ctx?.scopeKey||'hos_2026',rows=(S.recentSessions||[]).filter(x=>x.scopeKey===scope);if(!rows.length)return '';return `<section class="recent-activities"><h2>当前题库范围 · 最近两次进度</h2><p class="muted">单独题库与每种混合范围分别保存，互不挤占；浏览错题本、收藏夹不会覆盖进度。</p>${rows.map(row=>{const exam=row.kind==='exam',s=exam?row.snapshot:row.snapshot.session,position=exam?row.snapshot.current:row.snapshot.current,n=exam?s.ids?.length:s.items?.length;return `<div class="panel resume-banner"><div><b>${exam?'未完成考试':'继续上次练习'}：${esc(s.title||'学习进度')}</b><span>第 ${Number(position||0)+1}/${n||0} 题 · ${esc(row.scopeKey.split('|').map(id=>BANK_RUNTIME?.ctx?.metas.get(id)?.name||'HOS题库').join('＋'))} · ${esc(window.BEIJING_CLOCK?.format(row.time)||new Date(row.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</span></div><div class="q-actions"><button class="btn primary" onclick="resumeSavedActivity('${esc(row.id)}')">${exam?'继续上次考试':'继续上次练习'}</button><button class="btn" onclick="discardSavedActivity('${esc(row.id)}')">放弃此进度</button></div></div>`}).join('')}</section>`;}
function pauseAndSave(){if(!session||session.finished)return navHome(true);if(session.kind!=='exam')return pausePractice();pauseExamTimer();if(!saveSession(false)){resumeExamTimer();return toast('保存失败，已留在当前考试，请先导出备份')}session=null;stopTimerTicker();navHome(true);toast('考试已保存，可从首页继续，暂停期间不计时');}
function resumeSavedActivity(id){let row=S.recentSessions.find(x=>x.id===id);if(!row)return toast('此进度已变化，请查看最近两次进度');if(BANK_RUNTIME&&row.scopeKey!==BANK_RUNTIME.ctx.scopeKey){if(!prepareRequiredPwaUpdate())return;return BANK_RUNTIME.applySelection(row.scopeKey.split('|'),{resumeActivity:id})}try{if(row.kind==='exam'){const snap=sanitizeLastSession(row.snapshot);if(!snap)throw Error('考试快照不完整');S.lastSession=snap;resumeLastSession();saveSession(false);}else{const p=row.snapshot,restored=decodePracticeSession(p.session);if(!Number.isInteger(p.current)||p.current<0||p.current>=restored.items.length)throw Error('练习位置无效');session=restored;current=p.current;resumePracticeTimer();renderQuestion();persistPractice();toast('已恢复原队列、作答和位置；暂停期间不计时');}}catch(e){toast('暂不能恢复：'+e.message+'。原记录仍保留，请导出备份。');}}
function discardSavedActivity(id,confirmed=false){const row=S.recentSessions.find(x=>x.id===id);if(!row)return;if(!confirmed){let modal=$('#discardActivityConfirm');if(!modal){modal=document.createElement('div');modal.id='discardActivityConfirm';modal.className='modal hidden';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','discardActivityTitle');modal.innerHTML='<div class="modal-card compact-modal"><div class="modal-head"><h2 id="discardActivityTitle">放弃这次进度？</h2></div><div class="modal-body"><p>只移除这一次未完成进度，其他进度、学习记录和历史成绩保留。</p><div class="q-actions"><button class="btn" data-discard-cancel>取消，保留进度</button><button class="btn danger" data-discard-confirm>确认放弃</button></div></div></div>';document.body.append(modal)}const expected=JSON.stringify(row),trigger=document.activeElement,close=()=>{modal.classList.add('hidden');if(trigger?.isConnected)trigger.focus()};modal.querySelector('[data-discard-cancel]').onclick=close;modal.querySelector('[data-discard-confirm]').onclick=()=>{const now=S.recentSessions.find(x=>x.id===id);close();if(!now||JSON.stringify(now)!==expected)return toast('进度已变化，请重新确认');discardSavedActivity(id,true)};modal.onclick=e=>{if(e.target===modal)close()};modal.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close()}};modal.classList.remove('hidden');modal.querySelector('[data-discard-cancel]').focus();return;}const old=S.recentSessions,last=S.lastSession;forgetActivity(id);if(S.lastSession?.paperId===id)S.lastSession=null;if(!saveStore()){S.recentSessions=old;S.lastSession=last;return}if(row.kind==='practice')try{const key='shenrenliu_practice_v1_'+(BANK_RUNTIME?row.scopeKey:'hos'),raw=JSON.parse(localStorage.getItem(key)||'null');if(raw?.session?.paperId===id)localStorage.removeItem(key)}catch(e){}renderHome();}
function restoreRecentRoute(){if(typeof URL!=='function')return;let url=new URL(location.href),id=url.searchParams.get('resumeActivity');if(!id)return;url.searchParams.delete('resumeActivity');history.replaceState(history.state,'',url.href);resumeSavedActivity(id);}

function practiceStorageKey(){return 'shenrenliu_practice_v1_'+(BANK_RUNTIME?.ctx?.scopeKey||'hos')}
function encodePracticeSession(src,depth=0){
 if(!src||depth>4)return null;
 const item=i=>{let {q,...r}=i;return {...r,questionId:q.id}};
 let out={...src,items:src.items.map(item),masteryPool:src.masteryPool?.map(item),presentedItems:src.presentedItems?.map(item)};delete out._activeSince;delete out._activeIndex;delete out.highTimeItems;
 if(src.parentFrame){out.parentFrame={...src.parentFrame};if(src.parentFrame.session)out.parentFrame.session=encodePracticeSession(src.parentFrame.session,depth+1)}return out;
}
function decodePracticeSession(src,depth=0){
 if(!src||depth>4||!['study','fillStudy','exam'].includes(src.kind)||src.kind==='exam'&&!src.finished||!Array.isArray(src.items)||!src.items.length||src.items.length>ALL_Q.length)throw Error('练习快照不完整');
 const item=i=>{let q=ALL_Q.find(q=>q.id===i.questionId);if(!q||!BANK_Q.some(x=>x.id===q.id)||!validatePaperItem(q,i.renderType,i.fillLevel||'standard'))throw Error('题目范围已变化');let answer=sanitizeSavedAnswer(q,i.renderType,i.answer,i.fillLevel||'standard'),snapshot=sanitizePresentation(i.presentationSnapshot,q);if(i.presentationSnapshot&&!snapshot)throw Error('题目呈现已变化 #'+(q.sourceQuestionId||q.id));return {...i,q,answer,presentationSnapshot:snapshot}};
 let out={...src,items:src.items.map(item),masteryPool:src.masteryPool?.map(item),presentedItems:src.presentedItems?.map(item)};
 if(out.masteryPool){let active=new Map(out.items.map(i=>[i.q.id,i]));out.masteryPool=out.masteryPool.map(i=>active.get(i.q.id)||i)}
 if(out.reviewMode==='presented'&&out.presentedItems)out.presentedItems=out.items;
 if(src.parentFrame){out.parentFrame={...src.parentFrame};if(src.parentFrame.session){out.parentFrame.session=decodePracticeSession(src.parentFrame.session,depth+1);if(!Number.isInteger(src.parentFrame.current)||src.parentFrame.current<0||src.parentFrame.current>=out.parentFrame.session.items.length)throw Error('来源位置无效')}}return out;
}
let practiceSaveTimer=null;
