function persistPractice(){if(!session||session.kind==='exam'||view==='practiceComplete')return false;flushExamTimer();try{let snap=JSON.stringify({version:1,time:Date.now(),current,session:encodePracticeSession(session)});if(snap.length>1800000)throw Error('练习队列过大');localStorage.setItem(practiceStorageKey(),snap);let previous=S.recentSessions;rememberActivity('practice',JSON.parse(snap));if(!saveStore()){S.recentSessions=previous;return false}return true}catch(e){return false}}
