let historyDisplayScope='current';
function examCompletion(rec){
 let n=rec.ids?.length||rec.count||0,rows=rec.questionTimes||[],known=rec.completionEvidence!==false&&rows.length===n&&n>0,full=known&&rows.every(r=>r.answered===true);
 let filled=known?rows.filter(r=>r.responseStatus==='attempted'||r.answered).length:0;
 return {complete:full,label:!known?'旧记录 · 完成情况不明':full?`完整卷 · ${n}/${n}题答完整`:`未完成 · 有效作答${filled}/${n}题 · 完成率${Math.round(rows.filter(r=>r.answered).length/n*100)}%${rec.learningPolicyVersion===2?'':' · 旧口径'}`};
}
function renderResultGroups(wrong){
 let partial=x=>x.blankResults?.some(r=>r.correct),groups=[['答错',wrong.filter(x=>hasAnsweredValue(x.answer)&&!partial(x)),true],['部分正确',wrong.filter(x=>hasAnsweredValue(x.answer)&&partial(x)),true],['看过未答',wrong.filter(x=>!hasAnsweredValue(x.answer)&&x.visited),false],['未到达',wrong.filter(x=>!hasAnsweredValue(x.answer)&&!x.visited),false]];
 return groups.map(([name,items,open])=>`<details class="panel pad result-group" ${open&&items.length?'open':''}><summary>${name} · ${items.length}题${!open?' · 尚未评估':''}</summary><div class="review-list">${items.map(x=>`<div class="review-item"><h4>${BANK_RUNTIME?esc(BANK_RUNTIME.label(x.q)):'#'+x.q.id} ${esc(itemStem(x))}</h4><p>${hasAnsweredValue(x.answer)?'你的答案：'+esc(answerDisplay(x.answer)):'未作答 · 学习能力尚未评估'}</p><details><summary>查看正确答案${!open?'（准备继续自测时可保持隐藏）':''}</summary><p>${esc(itemAnswers(x).join('；'))}</p>${hasAnsweredValue(x.answer)&&x.blankResults?`<p>${x.blankResults.map(z=>`第${z.index}空${z.correct?'✓ 正确':'需改正'}`).join(' · ')}</p>`:''}</details><button class="btn small" onclick="reviewCurrentQuestion(${x.q.id})">${open?'重练这题':'开始练习（答案隐藏）'}</button></div>`).join('')||'<p>本组没有题目。</p>'}</div></details>`).join('');
}
// Legacy cleanup is deliberately conservative: zero time alone is never evidence.
function legacyCleanupCandidates(){
 let refs=new Map();for(const h of S.history||[]){if(h.learningPolicyVersion===2||h.paperDamaged||!h.ids?.length||h.userAnswers?.length!==h.ids.length||h.questionTimes?.length!==h.ids.length)continue;
  h.ids.forEach((id,i)=>{let t=h.questionTimes.find(t=>t.id===id);if(!Q.some(q=>q.id===id)||hasAnsweredValue(h.userAnswers[i])||!t||t.answered!==false||t.correct||t.ms!==0)return;let rows=refs.get(id)||[];rows.push({h,t});refs.set(id,rows)})}
 return [...refs].filter(([id,rows])=>{let n=rows.length,l=S.learning[id],w=S.wrong[id],a=S.aggregateStats?.byQuestion?.[id];return l&&w&&a&&l.attempts===n&&l.correct===0&&l.wrong===n&&l.totalMs===0&&l.timedAttempts===0&&w.wrongTotal===n&&w.count>0&&w.lastUserAnswer===null&&w.lastPresentation&&a.attempts===n&&a.correct===0&&a.wrong===n&&a.totalMs===0}).map(([id,rows])=>({id,rows}));
}
function legacyHistoryPanel(){let n=(S.history||[]).filter(h=>h.learningPolicyVersion!==2).length;return n?`<div class="panel pad legacy-policy"><b>历史规则说明</b><p>2026-10-21起，整题空白转为待练，不再增加知识错题。此前 ${n} 场旧口径记录及原分数保留；未能确定为空白的记录不自动扣减。</p><button class="btn small" onclick="previewLegacyCleanup()">检查有明确空白证据的旧记录</button><button class="btn small" onclick="undoLegacyCleanup()">撤销最近一次整理</button></div>`:''}
function cleanupKey(){return practiceStorageKey()+'_legacy_undo'}
function previewLegacyCleanup(){let rows=legacyCleanupCandidates(),old=$('#legacyCleanupDialog');old?.remove();let d=document.createElement('dialog');d.id='legacyCleanupDialog';d.className='feedback-dialog';d.innerHTML=`<h3>历史空白记录整理预览</h3><p>找到 ${rows.length} 道可确认仅由旧版空白形成的错题。只整理证据完全一致的记录，原卷分数不变。</p><p>${rows.map(r=>esc(BANK_RUNTIME?BANK_RUNTIME.label(ALL_Q.find(q=>q.id===r.id)):'#'+r.id)).join('、')||'其余记录证据不足或已有后续作答，保留为旧口径。'}</p><p>整理后转入待练，并同步移除这些空白产生的作答、错误和薄弱统计。撤销仅在整理后没有新增学习记录时可用，避免覆盖后续学习。</p><div class="q-actions"><button class="btn primary" onclick="applyLegacyCleanup()" ${rows.length?'':'disabled'}>确认转为待练</button><button class="btn" onclick="document.querySelector('#legacyCleanupDialog').close()">取消</button></div>`;document.body.append(d);d.showModal()}
function applyLegacyCleanup(){
 let candidates=legacyCleanupCandidates();if(!candidates.length)return toast('没有满足严格证据条件的记录');let before=packStore(S),ag=S.aggregateStats,subtract=(o,key,n)=>{if(o)o[key]=Math.max(0,num(o[key],0)-n)};
 try{localStorage.setItem(cleanupKey(),JSON.stringify({before,after:''}))}catch(e){return toast('无法保存撤销记录，本次未修改')}
 for(const {id,rows} of candidates){let n=rows.length,q=ALL_Q.find(q=>q.id===id),l=S.learning[id],w=S.wrong[id];for(const key of ['attempts','wrong'])subtract(l,key,n);l.streak=0;l.due=0;w.count=0;w.wrongTotal=0;w.wrongStreak=0;w.corrected=false;S.pendingPractice[id]={status:'unreached',time:Date.now()};delete S.difficultyProgress[id];subtract(ag,'totalAnswers',n);for(const key of ['attempts','wrong'])subtract(ag.byQuestion[id],key,n);for(const tag of q.tags||[])subtract(ag.byTag[tag],'attempts',n);for(const {h,t} of rows){subtract(ag.byType[t.type],'attempts',1);subtract(ag.weeks[new Date(h.time).toISOString().slice(0,10)],'attempts',1)}}
 if(!saveStore()){S=hydrateStore(JSON.parse(before));return toast('整理保存失败，已恢复原记录')}
 try{localStorage.setItem(cleanupKey(),JSON.stringify({before,after:packStore(S)}))}catch(e){S=hydrateStore(JSON.parse(before));saveStore();return toast('无法保存撤销凭据，已恢复整理前记录')}$('#legacyCleanupDialog')?.close();renderHistory(historyDisplayScope);toast(`已将 ${candidates.length} 道历史空白错题转为待练，原成绩保留`);
}
function cleanupSignature(value){const sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v;return JSON.stringify(sort(hydrateStore(JSON.parse(value))))}
function undoLegacyCleanup(){let rec;try{rec=JSON.parse(localStorage.getItem(cleanupKey())||'null')}catch(e){}if(!rec?.after)return toast('没有可撤销的整理');if(cleanupSignature(packStore(S))!==cleanupSignature(rec.after))return toast('整理后记录已有变化，为保护新学习数据，不覆盖恢复；整理前备份仍保留在本机');let currentStore=S;S=hydrateStore(JSON.parse(rec.before));if(!saveStore()){S=currentStore;return toast('恢复保存失败，当前记录保留')}localStorage.removeItem(cleanupKey());renderHistory(historyDisplayScope);toast('已撤销历史空白记录整理')}

function topicMeta(){const selected=BANK_RUNTIME?.ctx?.selected;return selected?.length===1?BANK_RUNTIME.ctx.metas.get(selected[0]):null}
function sanitizeContentTopics(value){let out={};if(value&&typeof value==='object'&&!Array.isArray(value))for(const [bank,group] of Object.entries(value)){const meta=BANK_RUNTIME?.ctx?.metas.get(bank);if(meta?.contentGroups?.some(g=>g.id===group))out[bank]=group;}return out}
function contentTopicId(){const m=topicMeta(),id=m&&S.settings.contentTopics?.[m.id];return m?.contentGroups?.some(g=>g.id===id)?id:'all'}
function contentTopicName(){return topicMeta()?.contentGroups?.find(g=>g.id===contentTopicId())?.name||'全部内容'}
function applyContentTopic(){const id=contentTopicId();Q=id==='all'?BANK_Q:BANK_Q.filter(q=>q.contentGroup===id)}
function contentTopicTitle(title,list){return contentTopicId()!=='all'&&list?.length&&list.every(q=>q.contentGroup===contentTopicId())?title+' · '+contentTopicName():title}
function selectContentTopic(id){if(view!=='home')return;const m=topicMeta();if(!m?.contentGroups||id!=='all'&&!m.contentGroups.some(g=>g.id===id))return;const previous=S.settings.contentTopics||{};S.settings.contentTopics={...previous,[m.id]:id};if(id==='all')delete S.settings.contentTopics[m.id];if(!saveStore()){S.settings.contentTopics=previous;return;}applyContentTopic();renderHome();toast('当前练习范围：'+contentTopicName()+' · '+Q.length+'题')}
function contentTopicPicker(){const m=topicMeta();if(!m?.contentGroups)return '';const id=contentTopicId();return `<section class="panel content-topics" aria-labelledby="contentTopicTitle"><h2 id="contentTopicTitle">按内容针对练习</h2><p>仍在同一个题库中，按实际考点区分；原题、答案和学习记录保留。</p><div class="content-topic-options" role="group" aria-label="内容练习范围">${[{id:'all',name:'全部内容',description:'完整157题；可参加45题综合模拟。'},...m.contentGroups].map(g=>{const questions=g.id==='all'?BANK_Q:BANK_Q.filter(q=>q.contentGroup===g.id);return `<button type="button" class="btn ${id===g.id?'primary':''}" aria-pressed="${id===g.id}" data-content-topic="${g.id}" onclick="selectContentTopic('${g.id}')">${esc(g.name)} · ${questions.length}题</button>`}).join('')}</div><p class="content-topic-description"><b>当前：${esc(contentTopicName())} · ${Q.length}题</b> · ${esc(id==='all'?'包括所有内容；综合模拟按全库组卷。':m.contentGroups.find(g=>g.id===id).description)}<br>新开始的刷题、背诵、填空和专项模拟均使用此范围；继续旧练习或旧试卷会保留原队列。</p><details><summary>分类依据</summary><p>按题目真正要求回答的知识区分，不按背景长短或关键词筛选。长案例若考使命、理念或行为准则，仍归入核心知识；问年份、经营数据、历史事件的题归入发展背景。</p></details></section>`}
function isOfficialCultureScope(){return !!(BANK_RUNTIME&&Q.length&&Q.every(q=>q.bankId==='sinotruk_culture_2025_official'))}
function officialCultureNotice(){let retired=BANK_RUNTIME?.retiredInfo?.();if(!isOfficialCultureScope()&&!retired)return '';return `<div class="notice"><b>${isOfficialCultureScope()?'正式企业文化题库 · 157题':'企业文化正式题库已更新'}</b><p>${isOfficialCultureScope()?'单选66题、判断54题、多选37题；51道精选题可切换为填空训练，原题仍完整保留。历史事项按所供2025资料口径学习。':''}${retired?'旧35题已退出练习，新题从零建立学习证据；旧记录已归档，完整备份继续保留，不套用到新题。':''}</p>${retired&&!window.QBANK_CLOUD_CONFIG?.enabled?'<button class="btn small" onclick="BANK_RUNTIME.openBackup()">备份与恢复</button>':''}</div>`}
function beginOfficialCultureExam(){
 if(contentTopicId()!=='all')return renderSpecialSetup('exam');
 let fills=coveragePick(Q.filter(q=>isFillEligible(q,'enhanced')),10),blocked=new Set(fills.map(q=>q.id)),regular=[];
 for(const [type,count] of [['single',15],['multiple',10],['judge',10]]){let picked=coveragePick(Q.filter(q=>q.type===type&&objectiveReady(q)),count,blocked);if(picked.length!==count)return toast('正式题库可用题量不足，未创建试卷');regular.push(...picked);picked.forEach(q=>blocked.add(q.id))}
 if(fills.length!==10)return toast('精选填空题量不足，未创建试卷');let paperId=makePaperId(),items=[...buildItems(regular,'study'),...buildItems(fills,'fill',0,'enhanced')];assignFillVariantKeys(items);applyOptionOrders(items,paperId);items.forEach(capturePresentation);
 session={kind:'exam',mode:'real',fillLevel:'enhanced',strict:$('#realExamRule')?.value==='strict',items,started:Date.now(),title:'企业文化综合模拟',finished:false,rotationRecorded:false,paperId};current=0;initExamTimer();saveSession();renderQuestion();
}
function openOfficialSource(q){
 if(isActiveExam())return;let active=session?.items?.[current];if(active?.q.id===q.id&&!active.checked){active.assisted=true;active.revealed=true;saveStore();if(view==='question')renderQuestion('preserve')}
 let old=$('#officialSourceDialog');old?.remove();let d=document.createElement('dialog');d.id='officialSourceDialog';d.className='feedback-dialog';d.innerHTML=`<h3>${esc(q.originalLabel)} · 正式资料原文</h3><p>重汽企业文化试题2025_.docx · 段落P${q.sourceParagraphs[0]}—P${q.sourceParagraphs.at(-1)}</p><p class="muted">原文含答案标记；未提交前查看会记为辅助学习。</p><p style="white-space:pre-wrap">${esc(q.sourceStemWithAnswer)}</p>${q.options.map((o,i)=>`<p>${String.fromCharCode(65+i)}. ${esc(o)}</p>`).join('')}<button class="btn primary" onclick="document.querySelector('#officialSourceDialog').close()">关闭原文</button>`;document.body.append(d);d.showModal();
}

function keepBlankVisible(){let input=document.activeElement;if(innerWidth>600||!input?.matches?.('.ultra-blank input'))return;requestAnimationFrame(()=>{if(input===document.activeElement&&input.isConnected)input.scrollIntoView({block:'center',behavior:'auto'})})}

function renderSearch(){view='search';app(`<div class="section-title"><div><h2>题库搜索</h2><p>按原题号、题干、选项、答案或知识标签查找</p></div><button class="btn" onclick="navHome()">返回</button></div><div class="panel pad"><div class="toolbar"><input id="searchInput" style="flex:1;min-width:160px" aria-label="搜索关键词" placeholder="例如：扭力扳手 / MES / 客户" oninput="doSearch(this.value)"><select id="searchType" aria-label="题型" onchange="doSearch($('#searchInput').value)"><option value="all">全部题型</option>${[['single','单选'],['multiple','多选'],['judge','判断'],['fill','填空']].filter(([t])=>ALL_Q.some(q=>q.type===t)).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><select id="searchScope" aria-label="搜索范围" onchange="doSearch($('#searchInput').value)"><option value="current">当前所选题库</option><option value="all">全部已加载题库</option></select><select id="searchMode" aria-label="搜索用途" onchange="setSearchMode(this.value)"><option value="reference" ${S.settings.searchMode!=='practice'?'selected':''}>查阅：显示答案</option><option value="practice" ${S.settings.searchMode==='practice'?'selected':''}>练习：隐藏答案</option></select></div><div id="searchResults" class="search-results" aria-live="polite"><div class="empty">输入关键词开始搜索</div></div></div>`)}

function doSearch(v){let kw=normalizeSearchText(v),type=$('#searchType').value,scope=$('#searchScope')?.value||'current',practice=($('#searchMode')?.value||S.settings.searchMode)==='practice',pool=scope==='all'?ALL_Q:Q;if(!kw.normalized){$('#searchResults').innerHTML='<div class="empty">输入关键词开始搜索</div>';return}let hits=pool.filter(q=>(type==='all'||q.type===type)&&questionSearchFields(q).some(text=>searchTextMatches(text,kw))),list=hits.slice(0,100);$('#searchResults').innerHTML=`<p class="search-count">${scope==='all'?'全部已加载题库':'当前所选题库'} · 找到 ${hits.length} 题${hits.length>100?'，先显示前100题，请缩小关键词':''} · ${practice?'练习模式：答案隐藏':'查阅模式：显示答案'}</p>`+(list.length?list.map(q=>{let fields=[['原题号',q.sourceQuestionId||q.id],['题干',q.stem],['选项',q.options.join(' ')],['答案',q.answers.join(' ')],['标签',q.tags.join(' ')],['题库',q.bankName||'HOS']],matched=fields.filter(([,text])=>searchTextMatches(text,kw)).map(([name])=>name);return `<div class="panel search-item"><strong>${esc(BANK_RUNTIME?BANK_RUNTIME.label(q):'#'+q.id)} · ${typeName(q.type)} · ${highlightSearch(displayText(q.stem),v)}</strong><p class="muted">命中：${matched.length?matched.join('、'):'填空变体'}${practice?'（答案内容已隐藏）':''}</p>${practice?'':`<p>答案：${highlightSearch(q.answers.map(displayText).join('；'),v)}</p>`}<p>${highlightSearch(q.tags.join(' / '),v)}</p><div class="q-actions"><button class="btn small" onclick="reviewOne(${q.id})">打开题目练习</button>${practice?'':`<button class="btn small" onclick="openQuestionSource(${q.id})">资料出处</button>`}</div></div>`}).join(''):'<div class="empty">没有匹配结果。可缩短关键词、改用原题号，或切换全部题型/全部题库。<button class="btn small" onclick="clearSearchFilters()">清除范围与题型限制</button></div>') }

function allTagStats(){let map=S.aggregateStats?.byTag||{};return Object.entries(map).map(([tag,z])=>{let n=num(z.attempts,0),correct=num(z.correct,0),ms=num(z.totalMs,0),slow=num(z.slow,0);return {tag,n,correct,ms,slow,wrong:n-correct,rate:n?correct/n:0,wrongRate:n?(n-correct)/n:0,slowRate:n?slow/n:0}}).sort((a,b)=>a.rate-b.rate||b.wrongRate-a.wrongRate||b.n-a.n)}
function weakTagStats(){return allTagStats().filter(x=>x.n>=3&&x.wrong>0).slice(0,5)}
function renderHistory(scope='current'){view='history';scope=scope==='all'?'all':'current';historyDisplayScope=scope;let ids=new Set(Q.map(q=>q.id)),h=(S.history||[]).map((x,index)=>({...x,index,...historyTimeAnalysis(x)})).filter(x=>scope==='all'||x.ids?.length&&x.ids.every(id=>ids.has(id))),ag=scope==='all'?(S.aggregateStats||emptyAggregate()):scopedAggregate(h),complete=h.filter(x=>examCompletion(x).complete),scores=complete.slice(0,20).map(x=>x.score),avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0,real=h.filter(x=>examCompletion(x).complete&&(x.examMode==='real'||x.mode==='真实考试模拟')),real5=real.slice(0,5),realAvg=real5.length?Math.round(real5.reduce((a,b)=>a+b.score,0)/real5.length):0,realHigh=real.length?Math.max(...real.map(x=>x.score)):0,realTime=real.length?real.reduce((a,b)=>a+(b.durationMs||0),0)/real.length:0,allTags=scope==='all'?allTagStats():scopedTagStats(),weak=allTags.filter(x=>x.n>=3&&x.wrong>0).slice(0,5),insufficient=allTags.filter(x=>x.n<3).slice(0,8),tagButton=x=>`<button class="btn" onclick="startTagStudy(${esc(JSON.stringify(x.tag))},${esc(JSON.stringify(scope))})"><b>${esc(x.tag)}</b><span>${x.n}题次 · 错误${x.wrong}次/${Math.round(x.wrongRate*100)}% · 正确率${Math.round(x.rate*100)}% · 平均${formatQTime(x.n?x.ms/x.n:0)}</span></button>`;app(`<div class="section-title"><div><h2>学习记录</h2><p>${scope==='all'?'全站累计含所有题库和历次记录':'当前所选题库：成绩仅纳入完整属于该范围的保留试卷；跨库整卷不拆分归属'}</p></div><button class="btn" onclick="navHome()">返回</button></div><div class="q-actions"><button class="btn ${scope==='current'?'primary':''}" onclick="renderHistory('current')">当前题库</button><button class="btn ${scope==='all'?'primary':''}" onclick="renderHistory('all')">全站累计</button></div><section class="dashboard-grid"><div class="panel pad"><b>${scope==='all'?'全部考试累计':'范围内保留场次'}</b><div style="font-size:32px;font-weight:800">${ag.totalExams||0}</div></div><div class="panel pad"><b>最近20场完整卷平均</b><div style="font-size:32px;font-weight:800">${scores.length?avg+'分':'暂无完整卷'}</div></div><div class="panel pad"><b>${scope==='all'?'全部考试最高分':'范围内记录最高分'}</b><div style="font-size:32px;font-weight:800">${ag.highestScore||0}分</div></div><div class="panel pad"><b>${scope==='all'?'总学习时长':'范围内累计作答用时'}</b><div style="font-size:32px;font-weight:800">${formatDuration(ag.totalStudyMs||0)}</div></div></section><div class="panel pad" style="margin-top:14px"><h3 style="margin-top:0">真实模拟 · 15单选 + 10多选 + 10判断 + 10填空</h3><div class="dashboard-grid"><div><span>记录内场次</span><strong>${real.length}</strong></div><div><span>最近5场平均</span><strong>${real.length?realAvg+'分':'暂无'}</strong></div><div><span>记录内最高</span><strong>${real.length?realHigh+'分':'暂无'}</strong></div><div><span>平均整场用时</span><strong>${real.length?formatDuration(realTime):'暂无'}</strong></div></div><p class="muted" style="margin-bottom:0">真实考试统计与普通模拟、冲刺等分开计算；本区只统计保留详细记录中确认全部答完整的试卷。原始分数均在下方保留；未完成或完成情况不明的旧卷不混入能力均分。</p></div>${legacyHistoryPanel()}<div class="panel pad" style="margin-top:14px"><h3 style="margin-top:0">薄弱知识点 Top 5</h3>${weak.length?`<div class="tag-weak-list">${weak.map(tagButton).join('')}</div>`:'<p class="muted">只列至少3题次且出现过错误的标签；全对标签不列入薄弱排行。</p>'}${insufficient.length?`<details style="margin-top:12px"><summary>数据不足（少于3题次）</summary><div class="tag-weak-list" style="margin-top:10px">${insufficient.map(tagButton).join('')}</div></details>`:''}</div><div class="panel pad" style="margin-top:14px"><ul class="list-clean history-list">${h.length?h.map((x,i)=>`<li><span>${new Date(x.time).toLocaleString()} · ${esc(x.mode)} · ${x.count}题 · ${examCompletion(x).label}${BANK_RUNTIME?' · '+esc(BANK_RUNTIME.bankIdsFor(x.ids).map(n=>BANK_RUNTIME.ctx.metas.get(n)?.name||n).join('＋')):''}${x.durationMs!=null?`<small>用时 ${formatDuration(x.durationMs)} · 平均 ${formatQTime(x.avgMs||0)} · 高耗时 ${x.highCount||0}题</small>`:''}</span><span class="history-actions"><b>${x.score}分</b>${x.ids?.length&&!x.paperDamaged?`<button class="btn small" onclick="reviewHistoryPaper(${x.index})">复盘</button> <button class="btn small" onclick="redoHistoryPaper(${x.index})">重做本卷</button>`:x.ids?.length?'<small>试卷数据损坏</small>':''}</span></li>`).join(''):'<li class="muted">暂无考试记录</li>'}</ul></div>`)}
function startTagStudy(tag,scope='current',masteryScope='all'){let origin=readCrossBankLearningOrigin()||capturePracticeFrame(),list=(scope==='all'?ALL_Q:Q).filter(q=>q.tags?.includes(tag));if(scope==='all'&&BANK_RUNTIME&&list.some(q=>!BANK_RUNTIME.isVisible(q))){localStorage.setItem('shenrenliu_learning_return_v1',JSON.stringify(origin));return BANK_RUNTIME.applySelection([...new Set(list.map(q=>q.bankId))],{studyTag:tag,studyMastery:masteryScope,returnLearning:'1'})}if(!list.length)return toast('该标签暂无题目');startStudySession(filterMastery(list,masteryScope),`专项：${tag}`,masteryScope);session.parentFrame=origin;persistPractice()}

function reviewHistorySlow(i){let rec=S.history?.[i],ids=new Set(rec?.highIds||[]);startReviewRecords(historyReviewRecords(rec).filter(r=>r.isCorrect&&ids.has(r.questionId)),'历史高耗时题复盘')}

function masteryStatus(q){let l=S.learning[q.id]||{},w=S.wrong[q.id]||{},avg=l.timedAttempts?l.totalMs/l.timedAttempts:0;if(S.reviewFlags[q.id])return '待复核';if((w.wrongStreak||0)>=2)return '反复错';if((w.count||0)>0)return '错题';if(l.due&&l.due<=Date.now())return 'SRS到期';if(avg>=30000)return '高耗时';if(S.favorites.includes(q.id))return '收藏';if((w.independentCorrectStreak||0)>=2||(S.mastery[q.id]==='mastered'&&(l.attempts||0)>0))return '熟练';if(S.mastery[q.id]==='fuzzy')return '不熟';return S.seen[q.id]?'不熟':'未见'}
function renderMasteryMap(filter='all'){view='masteryMap';let rows=Q.map(q=>({q,status:masteryStatus(q)})),mastered=rows.filter(x=>x.status==='熟练'),seven=Date.now()-7*86400000,recent=mastered.filter(x=>(S.wrong[x.q.id]?.lastCorrect||S.learning[x.q.id]?.last||0)>=seven).length,due=Q.filter(q=>{let l=S.learning[q.id],w=S.wrong[q.id];return l?.due>0&&l.due<=Date.now()||w?.count>0||S.mastery[q.id]==='fuzzy'}).length,everWrong=Q.map(q=>S.wrong[q.id]).filter(w=>(w?.wrongTotal||0)>0),corrected=everWrong.filter(w=>w.corrected).length,statuses=[...new Set(rows.map(x=>x.status))],filtered=rows.filter(x=>filter==='all'||filter==='pending'&&S.pendingPractice[x.q.id]||x.status===filter),multi=new Set(Q.map(q=>q.bankId)).size>1;app(`<div class="section-title"><div><h2>当前范围掌握地图</h2><p>本轮题号用于翻题，原题号用于查资料；此处按原题号排列。</p></div><button class="btn" onclick="navHome()">返回</button></div><section class="dashboard-grid"><div class="panel pad"><b>有证据掌握率</b><div class="big-time">${Math.round(mastered.length/Math.max(1,Q.length)*100)}%</div></div><div class="panel pad"><b>近7天活跃掌握题</b><div class="big-time">${recent}</div></div><div class="panel pad"><b>待巩固</b><div class="big-time">${due}</div></div><div class="panel pad"><b>错题纠正率</b><div class="big-time">${everWrong.length?Math.round(corrected/everWrong.length*100):0}%</div></div></section><div class="panel pad" style="margin-top:14px"><details><summary>状态与统计说明</summary><p>到期复习仅计算复习日期已到的题；待巩固按题目去重，包含到期、当前错题、标记不熟。待练为考试整题空白，不计知识错题。</p><p>熟练须有独立连续答对证据，或手动标为掌握且有作答记录。看过、收藏和辅助答对不等于独立掌握。每题显示优先级最高的状态，筛选待练独立计算。</p></details><div class="toolbar"><label>筛选状态 <select onchange="renderMasteryMap(this.value)">${[['all','全部'],['pending','待练'],...statuses.map(v=>[v,v])].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></label><span>${filtered.length}/${rows.length}题</span></div><div class="mastery-map">${filtered.map(({q,status})=>`<button class="mastery-cell" data-status="${status}" title="${esc(q.stem)}" onclick="reviewOne(${q.id})"><b>${esc(q.originalLabel||'#'+(q.sourceQuestionId||q.id))}${multi?' · '+esc(q.bankName):''}</b><span class="map-stem">${esc(displayText(q.stem).slice(0,50))}</span><small>${status}${S.pendingPractice[q.id]?' · 待练':''}</small></button>`).join('')||'<p>当前筛选没有题目。</p>'}</div></div>`)}

function openQuestionSource(id){let q=ALL_Q.find(x=>x.id===Number(id));if(!q)return toast('未找到题目资料');if(q.bankId==='sinotruk_culture_2025_official')return openOfficialSource(q);if(q.type==='fill'&&q.sourceReferences?.length){if(isActiveExam())return;openReferenceDialog(q);return;}sourceMeta=BANK_RUNTIME?BANK_RUNTIME.bankFor(q):null;sourcePages=getSourcePages(q);if(!sourcePages.length)return toast('该题库没有关联本题原图');sourcePage=sourcePages[0];let m=$('#sourceModal');m.classList.remove('hidden');renderSource()}
function openSource(page){sourceMeta=BANK_RUNTIME?BANK_RUNTIME.ctx.metas.get('hos_2026'):null;sourcePages=[];sourcePage=Math.max(1,Math.min(111,Number(page)||1));let m=$('#sourceModal');m.classList.remove('hidden');renderSource()}
function renderSource(){ensureSourceTools();sourceZoom=1;applySourceZoom();let prev=$('#sourcePrevButton'),next=$('#sourceNextButton');if(prev)prev.disabled=sourcePage<=1;if(next)next.disabled=sourcePage>=(sourceMeta?.sourcePageCount||111);let img=$('#sourceImage');if($('#sourcePageInput')){$('#sourcePageInput').value=sourcePage;$('#sourcePageInput').max=sourceMeta?.sourcePageCount||111}img.src=`${sourceMeta?.sourceBase||'source'}/image${sourcePage}.webp`;let span=sourcePages.length>1?` · 本题跨第 ${sourcePages.join('、')} 页`:'';$('#sourceTitle').textContent=`原题截图 · ${sourceMeta?.name||'HOS'} · 第 ${sourcePage}/${sourceMeta?.sourcePageCount||111} 页${span}`;img.onerror=()=>{img.alt='原题图片未找到';toast('原题图片未找到')};}
