function buildIdentityText(){const version=currentInstallState().currentVersion||document.querySelector('meta[name="build-version"]')?.content,time=document.querySelector('meta[name="build-time"]')?.content;if(!version||version.includes('__BUILD_VERSION__'))return '';let date=time&&!Number.isNaN(Date.parse(time))?new Date(time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未标时间';return '<br>本机发布：'+esc(date)+' · 批次 '+esc(version.slice(0,8))+' · '+(currentInstallState().webviewFallback?'网页更新模式':'离线更新模式')}
function openSettings(){let m=$('#settingsModal');m.classList.remove('hidden');$('#themeSetting').value=S.settings.theme;$('#wmSetting').value=S.settings.watermark;if($('#shuffleSetting'))$('#shuffleSetting').value=S.settings.shuffleOptions===false?'off':'on';if($('#confidenceSetting'))$('#confidenceSetting').value=S.settings.confidenceRequired?'required':'optional';if($('#eggMuteSetting'))$('#eggMuteSetting').checked=!!S.settings.eggMuted;renderShortcutEditor();let standard=Q.filter(isFillEligible).length,enhanced=Q.filter(q=>isFillEligible(q,'enhanced')).length,added=enhanced-standard,multi=Q.filter(q=>q.type==='multiple'&&isFillEligible(q,'enhanced')).length,single=Q.filter(q=>q.type==='single'&&isFillEligible(q,'enhanced')).length,judge=Q.filter(q=>q.type==='judge'&&isFillEligible(q,'enhanced')).length;if($('#versionStats'))$('#versionStats').innerHTML=`<b>版本与完整性</b><br>${APP_VERSION} ${APP_EDITION}${buildIdentityText()} · ${Q.length}题 · 标准填空${standard} · 增强新增${added} · 合计${enhanced}<br>增强池来源：单选${single} + 多选${multi} + 判断${judge} · Schema ${STORE_SCHEMA_VERSION}<br>${backupStatusText()}`}
function saveSettings(){let shortcuts=$$('.shortcutSetting').map(x=>x.value);if(shortcuts.length!==4||new Set(shortcuts).size!==4||shortcuts.some(id=>!SHORTCUTS.some(x=>x.id===id)))return toast('请选择四个不同的有效快捷入口');S.settings.theme=$('#themeSetting').value;S.settings.watermark=$('#wmSetting').value;S.settings.shuffleOptions=$('#shuffleSetting')?.value!=='off';S.settings.confidenceRequired=$('#confidenceSetting')?.value==='required';S.settings.eggMuted=!!$('#eggMuteSetting')?.checked;S.settings.homeShortcuts=shortcuts;if(shortcutEditorChanged)S.settings.quickEntryCustomized=true;else if(shortcutEditorReset)S.settings.quickEntryCustomized=false;if(!saveStore())return;$('#settingsModal').classList.add('hidden');renderHome();toast('设置已保存，首页快捷入口已更新')}
function resetData(){if(BANK_RUNTIME)return BANK_RUNTIME.resetSelected();if(!confirm('确定清空错题、收藏、掌握状态和考试记录吗？'))return;clearPracticeSnapshot();S=freshDefaultStore();saveStore();$('#settingsModal').classList.add('hidden');document.body.classList.remove('sheet-open');renderHome();toast('学习数据已清空')}
// Import is user-initiated, local-only and transactional. Never add counters from two snapshots.
const TRANSFER_BACKUP_KEY=STORE_KEY+'_before_transfer_v1';
let transferPending=null,transferTicket=0;
function transferMessage(text,error=false){let el=$('#transferStatus');el.textContent=text;el.classList.toggle('transfer-error',error)}
function closeTransfer(){transferTicket++;transferPending=null;$('#transferModal').classList.add('hidden');$('#transferOutput').value='';$('#transferInput').value='';}
function openTransfer(){if(BANK_RUNTIME)return BANK_RUNTIME.openBackup();if(isActiveExam()){toast('请先完成或退出当前考试，再进行数据迁移');return}$('#settingsModal').classList.add('hidden');transferPending=null;transferTicket++;$('#transferModal').classList.remove('hidden');$('#transferInput').value='';$('#transferOutput').value='';$('#transferMode').value='merge';$('#transferPreview').textContent='尚未预览。';describeTransferMode();$('#transferCompatible').checked=true;$('#transferApply').disabled=true;$('#transferCopy').disabled=true;$('#transferGenerate').disabled=false;try{$('#transferUndo').disabled=!localStorage.getItem(TRANSFER_BACKUP_KEY);$('#transferDownloadBackup').disabled=$('#transferUndo').disabled}catch(e){$('#transferUndo').disabled=true;$('#transferDownloadBackup').disabled=true}transferMessage('只在本机处理，不上传数据。迁移码包含学习信息，不是加密密码，请勿公开分享。')}
async function generateTransferCode(){if(isActiveExam())return toast('考试进行中不能迁移');const ticket=++transferTicket,button=$('#transferGenerate');button.disabled=true;$('#transferCopy').disabled=true;$('#transferOutput').value='';try{let data=window.QBANK_TRANSFER.makeLite(S),code=await window.QBANK_TRANSFER.encode(data,true);if(ticket!==transferTicket)return;$('#transferOutput').value=code;$('#transferCopy').disabled=false;transferMessage(`已生成 ${code.length.toLocaleString()} 字符${code.startsWith('SLQ1.G.')?'压缩':'兼容'}迁移码。${code.length>12000?'内容较长，聊天软件可能截断，建议使用完整文件备份。':'复制后私发给新设备，再粘贴预览导入。'}`)}catch(e){if(ticket===transferTicket)transferMessage(e.message||'生成失败，请使用文件备份',true)}finally{button.disabled=false}}
async function copyTransferCode(){const code=$('#transferOutput').value;if(!code)return;const copied=await copyText(code);if(copied)transferMessage('迁移码已复制，请私发给新设备。新设备粘贴后须先预览。');else{$('#transferOutput').focus();$('#transferOutput').select();transferMessage('浏览器未允许自动复制，已选中迁移码，请长按或手动复制。',true)}}
function resetTransferPreview(){transferTicket++;transferPending=null;$('#transferApply').disabled=true;$('#transferPreview').textContent='尚未预览。';}
function describeTransferMode(){const replace=$('#transferMode').value==='replace';$('#transferRules').textContent=replace?'覆盖仅替换错题、收藏、掌握标签、待复核和复习进度；不改考试历史、累计成绩、设置、彩蛋或未完成试卷。会先保存完整本机备份。':'合并：收藏/待复核取并集；同题错题与复习状态按记录时间判断，时间相同保留本机；掌握标签以迁移码为准；填空轮换取较大进度。同题累计学习次数保留较多的整条统计，错题累计次数取较大值，均不相加。考试历史和累计成绩不迁移。'}
async function previewTransferCode(){if(isActiveExam())return toast('请先退出当前考试');transferPending=null;$('#transferApply').disabled=true;const ticket=++transferTicket;transferMessage('正在检查迁移码…');try{const data=await window.QBANK_TRANSFER.decode($('#transferInput').value);if(ticket!==transferTicket)return;const p=window.QBANK_TRANSFER.preview(data);transferPending=data;$('#transferPreview').textContent=`精简迁移码 · 生成时间 ${new Date(p.createdAt).toLocaleString()}\n收藏 ${p.favorites} 题 · 当前错题 ${p.wrong} 题 · 掌握标签 ${p.mastery} 题\n待复核 ${p.review} 题 · 已练覆盖 ${p.seen} 题 · 单题学习/复习进度 ${p.progress} 题\n不包含考试历史、累计成绩、彩蛋、设置或未完成考试。`;$('#transferApply').disabled=false;describeTransferMode();transferMessage('校验通过，可选择合并或覆盖。校验只检测损坏，不验证发送者身份。')}catch(e){if(ticket===transferTicket){$('#transferPreview').textContent='未导入任何内容。';transferMessage(e.message||'迁移码读取失败',true)}}}
function applyTransferCode(){if(!transferPending)return;if(isActiveExam())return toast('请先退出当前考试');const mode=$('#transferMode').value;if(mode==='replace'&&!confirm('仅覆盖精简迁移范围内的本机记录。考试历史和累计成绩保留，系统会先保存完整本机备份。确定覆盖吗？'))return;try{const merged=window.QBANK_TRANSFER.merge(S,transferPending,mode),next={...hydrateStore(merged),easterEggs:sanitizeEggState(S.easterEggs)},backup=packStore(S);localStorage.setItem(TRANSFER_BACKUP_KEY,backup);localStorage.setItem(STORE_KEY,packStore(next));S=next;closeTransfer();document.body.classList.remove('sheet-open');renderHome();toast(mode==='replace'?'精简迁移已覆盖，可在迁移窗口撤销':'精简迁移已合并，可在迁移窗口撤销')}catch(e){transferMessage('导入未完成，本机记录未改变：'+(e.message||'存储不可用')+'。请先导出文件备份后重试。',true)}}
function readTransferBackup(){const raw=localStorage.getItem(TRANSFER_BACKUP_KEY);if(!raw)throw Error('没有可恢复的迁移前备份');const data=unpackStore(JSON.parse(raw));return {...hydrateStore(data),easterEggs:sanitizeEggState(data.easterEggs)}}
