function downloadTransferBackup(){try{const data=readTransferBackup(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`神人刘题库_迁移前完整备份_${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);transferMessage('迁移前完整备份已导出')}catch(e){transferMessage(e.message,true)}}
