function importData(file){if(BANK_RUNTIME)return BANK_RUNTIME.importBackup(file);if(!file)return;if(isActiveExam())return toast('请先退出当前考试再导入文件');let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(!d||typeof d!=='object'||Array.isArray(d))throw Error('根节点必须是对象');let sourceVersion=schemaVersionOf(d);if(d.history!=null&&!Array.isArray(d.history))throw Error('history字段格式错误');DATA_WARNINGS=[];let migrated={...hydrateStore(d),easterEggs:sanitizeEggState(d.easterEggs)};if(!confirm(`完整文件导入将整体替换本机学习数据：收藏${migrated.favorites.length}题、历史考试${migrated.history.length}场。系统会先保存本机备份。确定导入吗？`))return;localStorage.setItem(TRANSFER_BACKUP_KEY,packStore(S));localStorage.setItem(STORE_KEY,packStore(migrated));S=migrated;document.body.classList.remove('sheet-open');renderHome();toast(sourceVersion===STORE_SCHEMA_VERSION?'学习数据已安全导入，可在迁移窗口撤销':`旧版学习数据已迁移到Schema ${STORE_SCHEMA_VERSION}，可在迁移窗口撤销`)}catch(e){toast(`导入失败，本机数据未改变：${e.message||'数据结构不正确'}`)}};r.readAsText(file)}

