window.CLOUD_SYNC?.attach({getStore:()=>S,questions:()=>ALL_Q,apply:async next=>{
  if(view!=='home'||isActiveExam())return false;
  const previous=S,stamp=packStore(S),scopes=next.__cloudActivityScopes||[];let data={...next};delete data.__cloudActivityScopes;
  if(scopes.length){const scope=BANK_RUNTIME?.ctx?.scopeKey||'hos_2026';data.lastSession=(data.recentSessions||[]).filter(r=>r.kind==='exam'&&r.scopeKey===scope).sort((a,b)=>b.time-a.time)[0]?.snapshot||null;}
  const safe=hydrateStore(data);if(packStore(safe)===stamp)return true;
  try{
    const recoveryKey=window.CLOUD_SYNC.recoveryKey(),token=window.CLOUD_SYNC.sessionToken();if(!recoveryKey)throw Error('账号状态已变化');
    await window.CLOUD_SYNC_RECOVERY.save(recoveryKey,JSON.parse(stamp));
    if(view!=='home'||isActiveExam()||packStore(S)!==stamp||window.CLOUD_SYNC.sessionToken()!==token)return false;
    if(saveDebounceTimer){clearTimeout(saveDebounceTimer);saveDebounceTimer=null;}
    S=safe;if(BANK_RUNTIME)BANK_RUNTIME.persistCloudStore(S,scopes);else localStorage.setItem(STORE_KEY,packStore(S));
    applyContentTopic();renderHome();return true;
  }catch(error){S=previous;throw error;}
}});

